(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["rl"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-rollout-prefix-cache-sharing"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-1\">一 · 一条被长尾拖死的 rollout 队列</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-2\">二 · 它到底改写了哪一项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-3\">三 · 它不解决什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-4\">四 · 引用计数泄漏：一个安静的死法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-5\">五 · 适用边界的量化判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-6\">六 · 边界之外：什么时候不该上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-7\">七 · 长尾采样把前缀池拖成显存黑洞：这套方案不解决什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-8\">八 · 调度分组：从请求流到 rollout group</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-9\">九 · 单次分块预填：把 prompt KV 变成可共享的块</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-10\">十 · 分叉块表：引用计数与私有后缀的建立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-11\">十一 · 并行 decode：按块表拼接的 attention 读路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-12\">十二 · 结束与回收：引用递减、长尾驻留与 LRU 保留</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-13\">十三 · 引用计数、长尾驻留与块表碎片：共享前缀的失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-14\">十四 · 时间项：把 G 次预填折叠成 1 次</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-15\">十五 · 显存项：$(G-1)L_p$ 的节省从哪来</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-16\">十六 · 块表与引用计数：可实现的伪代码骨架</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-17\">十七 · 收益的边界条件：$L_p$ 占比与 $G$ 的取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-18\">十八 · 与相邻机制的公式对照</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-19\">十九 · 共享前缀的边界：驻留、引用与回收的三重代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-20\">二十 · 请求形态：G 条同源采样的“组”才是调度单元</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-21\">二十一 · 长度分布：L_p 占比决定收益，L_o 长尾决定驻留</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-22\">二十二 · 并发与批大小：前缀池容量反推可驻留组数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-23\">二十三 · 负载不对时的三种塌陷</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-24\">二十四 · 配方落地：按 prompt 长度分档的参数表</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-25\">二十五 · 负载配方：什么请求形态才配得上共享前缀池</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-26\">二十六 · 硬件档位与前缀池的驻留预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-27\">二十七 · 并行拓扑：组内并行与组间并行的取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-28\">二十八 · 量化方案：共享块的低精度一致性约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-29\">二十九 · KV策略：LRU热点保留与引用中块的隔离</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-30\">三十 · 调度参数：以组为单位的准入与长尾定价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-31\">三十一 · 可复现的配置思路：从负载画像到参数落位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-32\">三十二 · 部署配方的边界条件：从“省”到“稳”的四个失效面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-33\">三十三 · 显存驻留时间：被长尾钉住的前缀块</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-34\">三十四 · 带宽：共享读放大与块表拼接的间接成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-35\">三十五 · 通信：跨组引用与池化边界的张力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-36\">三十六 · 功耗与SLO：预填塌缩后的尾延迟结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-37\">三十七 · 引用计数与碎片：规模上去后的隐性泄漏</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-38\">三十八 · 前缀池的规模拐点：显存驻留、块表开销与长尾如何吃掉收益</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-39\">三十九 · 精度漂移：共享块的低精度一致性约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-40\">四十 · OOM与引用计数泄漏：池容量被静默吃掉</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-41\">四十一 · 批抖动与路由不均：组绑定打乱批组成</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-42\">四十二 · 尾延迟尖刺：长尾驻留与块表拼接</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-43\">四十三 · 监控面与回滚路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-44\">四十四 · 长尾驻留、引用泄漏与误淘汰：共享前缀池的三类失效面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-45\">四十五 · 对照轴：空间共享、时间混合、价值筛选</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-46\">四十六 · 决策表：按负载形态与瓶颈定位选型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-47\">四十七 · 与时间混合算法的组合判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-48\">四十八 · 与价值筛选算法的取舍：样本分布 vs 显存回收</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-49\">四十九 · 与分离式部署的边界：传输成本决定分层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rollout-prefix-cache-sharing-sec-50\">五十 · 选型的工程判断线</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:552px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 551.7 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"469.7\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">调度器按prompt分组，将同一prompt的G条请求绑定为一个rollo…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"469.7\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">为每条采样分配独立的decode KV块序列，其块表前段指向共享promp…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"469.7\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">decode循环中G条采样以continuous batching并行推进…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"469.7\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">某条采样结束（EOS或max_len）时释放其私有块并递减前缀块引用计数，…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"469.7\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">整组rollout结束后把token id与logprob打包送回训练侧，…</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-1\">一 · 一条被长尾拖死的 rollout 队列</h3>\n<p>某 RL 后训练集群在夜间跑一个 8K prompt 的采样任务，G=8。上线前容量规划按“每 prompt 一份 KV”估算，认为显存足够。实际运行两小时后，rollout 队列的排队延迟开始线性上升，随后大批请求超时被丢弃，训练侧拿到的轨迹数不足，整个 batch 被迫重跑。事后定位不是算力不够，而是显存：每条采样都从头预填同一段 prompt，prompt 的 KV 被重复计算 8 次，KV 占用按 G 倍膨胀；同时预填算力在长 prompt 下占到 rollout 总 FLOPs 的 30% 以上，预填队列与 decode 队列互相挤占。更致命的是，即便后来加了共享，组内长短样本差异极大——最短的采样几十个 token 就 EOS，最长的跑满 max_len——短样本结束后前缀块仍被最长样本引用，无法释放，KV 池的实际可用容量远低于账面值。这个事故说明：rollout 的成本结构不是“平均每 token 多少钱”，而是由最长的那条轨迹和重复预填共同决定的。</p>\n<p>把这件事写成式子，问题的形状就清楚了：</p>\n<div class=\"formula\">$$T_{\\text{rollout}} \\approx T_{\\text{prefill}}(L_p) + G\\cdot T_{\\text{decode}}(L_o),\\quad M_{\\text{KV}} = \\underbrace{L_p d_h n_l b}_{\\text{共享前缀}} + G\\cdot \\underbrace{L_o d_h n_l b}_{\\text{私有后缀}}$$</div>\n<p>朴素实现里第一项被乘上 G，第二项的前缀部分也被乘上 G。前者是算力浪费，后者是显存浪费，两者在长 prompt 下同时放大。Rollout 前缀 KV 共享要处理的正是这个乘数：把 prompt 的预填从 G 次压到 1 次，把前缀 KV 从 G 份压到 1 份。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-2\">二 · 它到底改写了哪一项</h3>\n<p>机制上，算法以 prompt 为单位建立前缀 KV 池。调度器按 prompt 分组，把同一 prompt 的 G 条请求绑定为一个 rollout group；先只对 prompt 做一次 chunked prefill，产出 prompt KV 块并登记到前缀池；随后为每条采样分配独立的 decode KV 块序列，其块表前段指向共享 prompt 块（引用计数 +1），后段为私有可写块。decode 循环中 G 条采样以 continuous batching 并行推进，每步只写各自新 token 的 KV，attention 读取时按块表拼接共享前缀与私有后缀。某条采样结束（EOS 或 max_len）时释放其私有块并递减前缀块引用计数，归零后前缀块回收到池；整组结束后 token id 与 logprob 打包送回训练侧，KV 池按 LRU 保留热点 prompt 前缀供下一轮复用。</p>\n<p>显存账因此变成：</p>\n<div class=\"formula\">$$M_{\\text{share}}=L_p+G\\cdot L_o,\\quad M_{\\text{naive}}=G\\cdot(L_p+L_o)$$</div>\n<p>节省量为 $(G-1)L_p$，长 prompt 下占比接近 $(G-1)L_p/M_{\\text{naive}}$。注意这个式子里 $L_o$ 没有被压缩——私有后缀是采样真正产生的新信息，无法共享。所以收益完全由 $L_p$ 在总占用中的比例决定，这也直接划出了适用边界。</p>\n<p>代价同样写在这个式子里。前缀块被 G 条采样共享读，只要组内还有一条采样在跑，引用计数就不为零，块就不能回收。组内长度差异大时，短样本先结束也释放不了前缀块，显存驻留时间被最长样本拉长。工程上这意味着：容量规划不能按平均 $L_o$ 算，必须按组内最长样本的驻留窗口算，否则就会出现第一节那种“账面够、实际不够”的局面。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-3\">三 · 它不解决什么</h3>\n<p>第一，它不减少 decode 的算力。G 条采样仍然要各自生成 $L_o$ 个 token，decode 阶段的 FLOPs 与 KV 写入量不变，只是不再重复读前缀。因此当 $L_p$ 远小于 $L_o$、或 prompt 很短时，收益随 $L_p$ 占比下降，算法退化为一次普通的批内共享，不值得为它付出块分配器的复杂度。</p>\n<p>第二，它不解决长尾本身。共享只消除重复，不消除组内最长样本对显存的占用。若某条采样异常长（例如反复不触发 EOS），它会拖住整组前缀块的释放，KV 池被单个长尾样本钉住。这与在线剪枝类方法的目标相反：本算法保留全部采样，只是让它们不重复预填；要处理低价值轨迹，得靠剪枝，而不是靠共享。</p>\n<p>第三，它不改变采样语义。共享前缀块的 attention 数值必须与逐条独立预填一致，量化档位未给出时，需保证共享块在低精度下 attention 数值一致，否则 G 条轨迹的 logprob 会与训练侧期望的分布产生系统性偏差。这是数值问题，不是调度问题。</p>\n<p>第四，它与时间维度的混合无关。分块预填搭载解码是在时间轴上交错 prefill 与 decode，本算法是在空间轴上让 G 条采样指向同一份 prompt KV；两者可以叠加，但共享本身不提供任何 prefill/decode 的时间重叠。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-4\">四 · 引用计数泄漏：一个安静的死法</h3>\n<p>块表跨请求共享使 PagedAttention 的块分配器必须支持引用计数与跨请求共享，实现复杂度与碎片管理成本上升。最典型的失败模式是引用计数泄漏：某条采样异常终止（超时、被调度器抢占、异常路径未走正常释放流程），私有块释放了，但前缀块的递减没有执行，引用计数永远大于零，前缀块永不回收。KV 池逐步耗尽，表现为“越跑越慢、重启就好”，很难在日志里抓到单点错误。</p>\n<p>伪代码层面，释放路径必须与分配路径严格对称：</p>\n<ul>\n<li>分配：<code>ref[prefix_block] += 1</code>，绑定到该采样的块表前段；</li>\n<li>释放：遍历块表，对前缀段执行 <code>ref -= 1</code>，对私有段直接回收；</li>\n<li>回收：仅当 <code>ref == 0</code> 时前缀块入池，且入池前需确认无在途 attention 读。</li>\n</ul>\n<p>另一类失败是 LRU 与共享块争抢显存：LRU 保留热点 prompt 前缀供下一轮复用，但若淘汰策略未区分“引用中”的块，可能误回收仍在被当前组读取的前缀块，引发错误结果而非报错。工程判断是：淘汰候选集必须排除 <code>ref &gt; 0</code> 的块，LRU 只在不被引用的块之间做选择；这会让池的有效容量进一步小于物理容量，容量规划要预留这部分余量。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-5\">五 · 适用边界的量化判据</h3>\n<p>把适用性写成可检查的条件，比定性描述更有用。三个判据：</p>\n<table class=\"mini\">\n<thead><tr><th>判据</th><th>含义</th><th>不满足时的后果</th></tr></thead>\n<tbody>\n<tr><td>$L_p$ 占比</td><td>prompt KV 块数在 $L_p+L_o$ 中的比例</td><td>收益随占比下降，短 prompt 下不值得引入引用计数</td></tr>\n<tr><td>组内长度方差</td><td>最长与最短采样的 $L_o$ 差距</td><td>前缀块驻留被长尾拉长，池有效容量低于预期</td></tr>\n<tr><td>G 的大小</td><td>同 prompt 采样条数</td><td>G 越大节省越多，但长尾驻留与引用计数开销同步放大</td></tr>\n</tbody>\n</table>\n<p>规模上限受组内最长样本驻留时间与块分配器引用计数开销约束，具体上限未给出，但方向明确：G 增大时 $(G-1)L_p$ 的节省线性增长，而前缀块的驻留窗口由最长样本决定、不随 G 缩小，因此单位显存的有效吞吐存在一个由长尾分布决定的天花板。实际部署中应把 rollout group 的 max_len 与组的并发数一起作为容量参数，而不是只按平均长度估算。</p>\n<p>一个具体例子：8K prompt、G=8、组内最长采样跑满 max_len 而多数采样提前结束。前缀块在整个最长样本生命周期内不可回收，这段时间里池中可分配的块只剩私有块空间；若并发组数按“前缀块可立即复用”来规划，就会在长尾组上出现分配失败。正确的做法是把前缀块视为“按组租用、租期等于最长样本”的资源，容量公式里对前缀块乘以一个由长尾决定的驻留系数，而不是乘以 1。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-6\">六 · 边界之外：什么时候不该上</h3>\n<p>三类场景应明确排除。其一，prompt 短、$L_o$ 长的生成型负载：$L_p$ 占比低，共享省下的显存与预填时间不足以抵消块分配器引用计数与碎片管理的实现成本，直接走普通 continuous batching 更稳。其二，组内长度分布极重尾且无有效截断：前缀块被单条异常长样本钉住，池容量被长尾吃掉，此时应先解决 max_len 与早停策略，再谈共享。其三，对数值一致性要求极高、且共享块需走低精度量化的场景：量化档位未给出，共享块在低精度下的 attention 数值一致性需要单独验证，验证成本高于收益时应退回逐条预填。</p>\n<p>反过来，最适配的形态是同一 prompt 多采样、长 prompt 占比高的 RL rollout：预填时间近似降为 1/G，KV 显存从 $G\\cdot(L_p+L_o)$ 降为 $L_p+G\\cdot L_o$，且组内长度相对齐整、长尾可控。判断是否上线，最终落在两个可测量的量上——前缀块在池中的平均驻留时长，以及引用计数泄漏导致的池容量衰减速率；前者决定容量规划，后者决定运维成本。这两个量比任何架构参数都更能说明该算法在你的负载上是否成立。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-7\">七 · 长尾采样把前缀池拖成显存黑洞：这套方案不解决什么</h3>\n<p>先看一个线上事故的形态。RL 后训练的一个 rollout 批次里，同一 prompt 采样 G 条轨迹，调度器按 prompt 分组、只做一次 chunked prefill，把 prompt KV 块登记进前缀池，G 条采样的块表前段全部指向它。问题出在组内长度分布：G 条轨迹里有几条在几十个 token 内就撞上 EOS，而组内最长的一条跑满了 max_len。短样本结束时释放私有块、递减引用计数，但前缀块的引用计数仍被最长样本持有，回收条件不成立。于是这块 8K prompt 的 KV 在整个组生命周期内被钉在池里，而池的容量是按“平均组时长”规划的，实际驻留被长尾拉到数倍。表现不是报错，而是新到的 rollout group 拿不到块、prefill 排队、整批 rollout 吞吐塌陷——一个本来用来省显存的机制，反过来成了显存碎片与排队延迟的来源。</p>\n<p>把账算清楚才能看出边界在哪。共享与朴素两种布局的 KV 占用分别为</p>\n<div class=\"formula\">$$M_{\\text{share}}=L_p+G\\cdot L_o,\\quad M_{\\text{naive}}=G\\cdot(L_p+L_o)$$</div>\n<p>节省量是 $(G-1)L_p$，长 prompt 下占比接近 $(G-1)L_p/M_{\\text{naive}}$。这个式子的含义很硬：收益完全由 $L_p$ 在总 KV 中的占比决定，且随 G 线性放大。反过来，短 prompt、长生成（$L_o \\gg L_p$）的负载里，$L_p$ 占比低，共享省下的显存与预填算力都有限，而引用计数、跨请求块表拼接、碎片管理的复杂度是实打实要付的。因此它适用于“同一 prompt 多采样 + 长 prompt 占比高”的 RL rollout，不适用于单条采样、prompt 短而 decode 长的在线服务，也不适用于组内长度分布极度偏斜的场景——后者恰恰是它失效最彻底的地方。</p>\n<p>它同样不解决另外两类问题。其一，它只消除重复预填，不减少 decode 步数：$T_{\\text{rollout}} \\approx T_{\\text{prefill}}(L_p) + G\\cdot T_{\\text{decode}}(L_o)$ 中第二项原封不动，长生成负载的延迟主项仍在 decode，靠共享前缀拿不到收益。其二，它保留全部 G 条轨迹，与在线剪枝放弃低价值轨迹是正交的两件事——前者在空间维度共享同一份 prompt KV，后者在数量维度减少采样，不能互相替代。失效条件可以归成一张短表：</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>后果</th><th>工程判断</th></tr></thead><tbody><tr><td>组内长度差异大</td><td>前缀块驻留被最长样本拉长，池可用容量低于规划值</td><td>按最长样本而非均值做容量规划，或对超长样本单独分组</td></tr><tr><td>引用计数泄漏</td><td>前缀块永不回收，池逐步耗尽</td><td>引用计数与块表变更纳入同一事务，加周期性对账</td></tr><tr><td>LRU 未区分引用中块</td><td>误回收仍在读的前缀块，attention 读到脏数据</td><td>淘汰候选集必须排除 refcount&gt;0 的块</td></tr><tr><td>$L_p$ 占比低</td><td>节省趋近于零，复杂度照付</td><td>按 $L_p/(L_p+L_o)$ 设阈值决定是否启用</td></tr></tbody></table>\n<p>还有一条容易被忽略的数值边界：共享块被 G 条采样同时读，若量化档位在组内不一致，或低精度下 attention 对同一前缀块的读出路径不同，共享就从“省”变成“数值不一致”的来源。部署时必须保证共享块在统一精度下被所有引用者读取，否则省下的显存会以轨迹质量漂移的形式还回来。规模上限因此不是由 G 单独决定，而是由组内最长样本驻留时间与块分配器引用计数开销共同约束：G 越大节省越多，长尾驻留与元数据开销也越重，拐点出现在“节省的显存”被“长尾多占的显存 + 引用计数管理成本”抵消之处。</p>\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-8\">八 · 调度分组：从请求流到 rollout group</h3>\n<p>进入引擎的请求并不是以“单条采样”为单位被看待的。调度器在每个调度步扫描等待队列，按 prompt 的规范化哈希（token id 序列，必要时含模板前缀）做一次分组归并：同一个 prompt 的 G 条请求被绑定成一个 rollout group，共享一个组标识与一份待预填的 prompt 描述。这一步的输入是请求队列中携带的 prompt token id、采样参数（temperature、top-p、max_len）与组内序号；输出是一个组对象，其字段包括 prompt 长度 L_p、组内成员列表、目标 G、以及一个尚未填充的前缀块句柄。代价发生在调度侧而非算力侧：分组需要一次哈希与查表，若组内成员到达时间离散（RL 训练侧常按批下发，但网络与前端排队会打散），调度器必须决定等待窗口——等太久拉低 GPU 利用率，等太短则组内 G 不满、共享收益打折。工程上把等待窗口与当前批的空闲 slot 数挂钩：批未满时优先补齐已有组，批将满时对新 prompt 立即开组。这一步不产生任何 KV 写入，但它决定了后续所有步骤的并行度上限：一个组就是一个 continuous batching 中的“超请求”，其成员在 decode 阶段必须同步推进。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-9\">九 · 单次分块预填：把 prompt KV 变成可共享的块</h3>\n<p>组建立后，引擎只对该 prompt 执行一次 chunked prefill。输入是 L_p 个 token，按 chunk 大小（受 SMEM 与 tcgen05 MMA 的 tile 形状约束）切段送入；每段前向产出该段的 K/V，经块分配器切成固定大小的 KV 块（如 16 或 32 token 一块），写入 HBM 中由前缀池管理的物理块，并在组对象上登记一个块表：逻辑块号到物理块号的映射，外加一个引用计数字段，初值置为 1（池自身持有）。输出是完整的 prompt 前缀 KV 与一份可被引用的块表。代价是这一阶段唯一的重算力开销：预填 FLOPs 正比于 L_p，在 8K 以上 prompt 下这部分占 rollout 总 FLOPs 的 30% 以上——正是被消除的那 G−1 份重复。时间上，chunked prefill 让长 prompt 不至于独占一个调度步，但也意味着前缀块要等最后一个 chunk 落盘才完整可用；在此之前组内成员只能等待，不能被调度进 decode。这里有一个容易被忽略的细节：预填时 attention 的因果掩码使不同 chunk 的 K/V 相互依赖，因此 chunk 间不能并行，只能顺序推进，预填延迟对 L_p 近似线性。</p>\n<div class=\"formula\">$$T_{\\text{rollout}} \\approx T_{\\text{prefill}}(L_p) + G\\cdot T_{\\text{decode}}(L_o)$$</div>\n<p>该式给出本算法的核心时间账：预填项不再乘 G。当 L_p 远大于 L_o、G 较大时，rollout 的墙钟时间由 G 次 decode 主导，预填被摊薄到近似 1/G。反过来，短 prompt、小 G 的场景里预填占比本就低，共享的边际收益随 L_p 占比下降而衰减——这是判断是否启用该机制的第一道门槛。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-10\">十 · 分叉块表：引用计数与私有后缀的建立</h3>\n<p>前缀块就绪后，引擎为组内每条采样分配一条独立的 decode KV 块序列。输入是组的前缀块表与成员序号；输出是 G 份新块表，每份的前段逻辑块直接指向共享 prompt 块，对应物理块的引用计数原子加一，后段则预留若干私有可写块（初始为空，随 decode 逐步追加）。这一步的代价是纯元数据操作：G 次块表拷贝与 G 次原子加，量级在微秒级，但它引入了一个结构性约束——块分配器必须从“请求独占块”升级为“跨请求共享块”，PagedAttention 的 free-list 管理要能区分“被引用中”与“可回收”，碎片整理不能再随意搬移共享块。显存账在此刻定型：</p>\n<div class=\"formula\">$$M_{\\text{share}}=L_p+G\\cdot L_o,\\quad M_{\\text{naive}}=G\\cdot(L_p+L_o)$$</div>\n<p>节省量为 (G−1)·L_p。以 8K prompt、G=8 为例，若 L_o 相对 L_p 很小，naive 方案下 prompt KV 被复制 8 份，共享后只剩 1 份，KV 池的有效容量近似扩大数倍——这是长 prompt 高 G 场景下最直接的显存红利。但注意私有块是“按需增长”的：每条采样的 L_o 由其生成长度决定，组内长度分布决定了实际占用，而不是分配时的预留。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-11\">十一 · 并行 decode：按块表拼接的 attention 读路径</h3>\n<p>decode 循环中，G 条采样以 continuous batching 的方式并行推进：每一步，组内所有未结束成员的新 token 被拼进同一个批，各自做一次单 token 前向。输入是上一步的 token 与各自的块表；输出是新 token 的 K/V 写入各自的私有块尾部，以及 logits 用于采样。关键在 attention 的读路径：query 只有一行（当前 token），但它要 attend 到“共享前缀 + 自身私有后缀”拼接而成的完整 KV 序列。实现上不是物理拼接，而是按块表逐块发起 paged attention——前段块表项指向共享物理块，多个成员在同一调度步读同一批物理块，形成广播式读取；后段指向各自私有块。代价有两面：算力上，每步 attention 的 KV 读取量正比于 L_p+L_o，与 naive 相同，共享节省的是预填而非 decode 的带宽；带宽上，共享前缀块被 G 条采样在同一时刻读取，若这些块在 HBM 中连续且被多 CTA 同时命中，L2 与 HBM 的访问模式反而更友好，但若块表映射分散，则 paged attention 的 gather 开销上升。另一个隐性代价是批内同步：组内成员必须在同一步推进，若某成员已到 EOS 而其他成员仍在生成，它占用的批 slot 空转，直到组内全部结束或调度器将其移出——这直接影响 decode 阶段的吞吐。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-12\">十二 · 结束与回收：引用递减、长尾驻留与 LRU 保留</h3>\n<p>某条采样命中 EOS 或达到 max_len 时，引擎释放其私有块序列，并对前缀块表做一次引用递减。输入是结束成员的块表与组标识；输出是更新后的引用计数，归零时前缀块被回收到池。这一步的代价不在计算而在驻留时间：只要组内还有一条采样在跑，前缀块就不能释放，引用计数始终大于零。组内长度差异越大，短样本结束后前缀块被“长尾”钉在显存里的时间越长，KV 池的实际可用容量低于按平均长度估算的预期——这是本机制最典型的失败模式，也是容量规划时必须按组内最长样本而非平均样本估算的原因。整组结束后，引擎把 G 条轨迹的 token id 与 logprob 打包送回训练侧；前缀池则按 LRU 保留热点 prompt 前缀，供下一轮 rollout 复用。LRU 与引用计数在此处必须协同：淘汰策略只能作用于引用计数为零的块，否则会误回收仍在被读的前缀块，引发 attention 读到脏数据或直接报错。引用计数泄漏（某条路径漏减）会让前缀块永不回收，池逐步耗尽——这是实现层面最需要加断言与周期性审计的地方。</p>\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入</th><th>输出</th><th>主要代价</th></tr></thead><tbody><tr><td>调度分组</td><td>请求队列、prompt 哈希</td><td>rollout group 对象</td><td>等待窗口拉低利用率</td></tr><tr><td>单次预填</td><td>L_p token、chunk 切分</td><td>前缀 KV 块 + 块表</td><td>预填 FLOPs 与线性延迟</td></tr><tr><td>分叉块表</td><td>前缀块表、成员序号</td><td>G 份块表、引用+1</td><td>分配器共享化、碎片管理</td></tr><tr><td>并行 decode</td><td>块表、上步 token</td><td>私有块追加、logits</td><td>批内同步空转、gather 带宽</td></tr><tr><td>结束回收</td><td>成员块表</td><td>引用−1、块回收</td><td>长尾驻留、LRU 与引用协同</td></tr></tbody></table>\n<p>把五步串起来看，本机制的性能上限由两个量夹住：一是组内最长样本的 L_o，它决定前缀块的驻留时长与批 slot 的占用；二是块分配器的引用计数开销，它随 G 与并发组数线性增长，在 G 很大时元数据操作本身会成为调度步的瓶颈。工程判断因此落在组大小与组内长度方差的权衡上：G 越大，预填节省越接近 1/G，但长尾驻留与引用管理成本同步上升；对长度方差大的 prompt（如开放式生成任务），按长度分桶后再组队、或对超长成员单独开组，往往比一味增大 G 更划算。共享块在低精度下的数值一致性也需在此环节守住——前缀块只算一次、被 G 条采样共同读取，任何量化误差都会被放大到全部轨迹上，因此前缀块的精度档位应与私有后缀的精度策略解耦评估。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-13\">十三 · 引用计数、长尾驻留与块表碎片：共享前缀的失效边界</h3>\n<p>共享前缀KV的收益来自“一份前缀被G条采样同时读”，代价也全部压在这个“同时”上。前缀块的释放条件不是“本组所有采样结束”，而是引用计数归零——短样本先到EOS时只释放自己的私有块并递减计数，前缀块仍被最长样本持有。于是前缀块的显存驻留时间由组内最长样本决定，而非平均长度。设组内采样长度为$L_o^{(1)}\\le\\dots\\le L_o^{(G)}$，前缀块占用时长为$\\max_i T_{\\text{decode}}(L_o^{(i)})$，这段时间内它不可被LRU淘汰、不可被其他prompt复用。若组内长度分布长尾明显（RL采样温度高时常见），前缀池的有效容量被显著压低：名义上池子能装$N$个prompt前缀，实际同时驻留的组数受最长样本拖累，短样本释放出的私有块也无法填补前缀块的空缺。</p>\n<p>第二个失效点是引用计数本身的正确性。块表跨请求共享要求PagedAttention的块分配器从“每请求独占块”升级为“块带引用计数、可跨请求只读映射”，这引入三类工程风险。其一是计数泄漏：某条采样异常终止（被调度器抢占、被max_len截断、被上层取消）时若未走正常释放路径，计数不减，前缀块永不回收，KV池逐步耗尽且不报错，表现为吞吐缓慢下滑而非显式OOM。其二是淘汰竞态：LRU按“最近使用”挑 victim，但正在被引用的块不能被选中，淘汰逻辑必须先查计数再决定，否则会回收仍在被attention读取的前缀块，产生数值错误而非崩溃，最难排查。其三是碎片：私有块按各采样长度独立增长，G条采样的块序列长度不一，块分配器在组结束时要回收大量尺寸参差的块，碎片率随G与长度方差上升。</p>\n<div class=\"formula\">$$M_{\\text{share}}=L_p+G\\cdot L_o,\\quad M_{\\text{naive}}=G\\cdot(L_p+L_o),\\quad \\Delta=(G-1)L_p$$</div>\n<p>把代价折算成系统指标：显存节省量$(G-1)L_p$是静态上限，实际可用节省要减去长尾驻留造成的“不可用容量”与碎片浪费。预填侧收益则相对刚性——prompt只做一次chunked prefill，预填时间近似降为$1/G$，这部分不受长尾影响，因为它在decode开始前就已完成。因此判断是否启用共享，应看两个比值：$L_p/(L_p+L_o)$决定显存收益是否值得引入引用计数复杂度，组内长度方差决定长尾驻留是否会把收益吃掉。长prompt（8K以上）、G较大、采样长度分布相对集中的场景收益最稳；短prompt或长度方差极大的场景，共享前缀的块表开销与驻留代价可能超过省下的预填算力。一个具体判断：当组内最长样本长度超过最短样本数倍时，前缀块的实际驻留成本已接近按最长样本单独预填的成本，此时应改为按长度分桶采样或对超长样本单独成组，避免一条长尾拖住整组前缀。</p>\n<p>还有一个容易被忽略的数值边界：共享前缀块被G条采样以不同私有后缀拼接读取，attention在块表拼接处要求前缀块的KV数值在低精度下保持一致。若前缀块以FP8/NVFP4写入而私有后缀用不同量化档位，拼接后的attention打分会出现档位不一致的偏差，且该偏差被G条采样同时放大。工程上应保证共享前缀块与其私有后缀使用同一量化档位，或在前缀块登记入池时就固定其精度格式，不允许后续请求以不同精度引用同一块。这一约束会限制池内块的精度多样性，是共享机制在混合精度部署下的隐性代价。</p>\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-14\">十四 · 时间项：把 G 次预填折叠成 1 次</h3>\n<p>核心时间公式是 <span class=\"formula\">$$T_{\\text{rollout}} \\approx T_{\\text{prefill}}(L_p) + G\\cdot T_{\\text{decode}}(L_o)$$</span> 逐项看：$T_{\\text{prefill}}(L_p)$ 是唯一一次对 prompt 做的分块预填，$L_p$ 为 prompt 长度（token 数）；$T_{\\text{decode}}(L_o)$ 是单条采样生成 $L_o$ 个 token 的增量解码时间；乘上 $G$ 表示组内 $G$ 条采样在 continuous batching 下并行推进，但每条都要走完自己的 $L_o$ 步。朴素做法的时间是 $G\\cdot T_{\\text{prefill}}(L_p)+G\\cdot T_{\\text{decode}}(L_o)$，两者相减，省掉的正是 $(G-1)\\cdot T_{\\text{prefill}}(L_p)$。</p>\n<p>推导的关键一步在于预填的批处理性质：预填是对整段 prompt 的一次矩阵乘，其 FLOPs 与 $L_p$ 近似线性，而 decode 每步只处理 1 个 token、受权重带宽约束。因此把 $G$ 条请求的 prompt 拼成一个 batch 做一次 chunked prefill，与逐条做 $G$ 次，算力开销差 $G$ 倍；而 decode 阶段因为 $G$ 条请求本来就要各走各的步，无法折叠。于是长 prompt 下 $T_{\\text{prefill}}$ 在总时间中的占比被压到 $1/G$ 量级——给定事实指出 8K 以上 prompt 的预填算力占 rollout 总 FLOPs 的 30% 以上，共享后这部分直接除以 $G$。</p>\n<p>工程代价落在调度器上：一次 chunked prefill 要覆盖 $G$ 条请求的公共前缀，意味着这 $G$ 条请求必须在同一时刻被绑定成组、同时到达预填队列。若采样请求是陆续到达的（例如上游按轨迹逐条下发），调度器要么等组凑齐（增加排队延迟），要么对先到者单独预填并让后到者复用已产出的前缀块——后者要求前缀池在组未满时也保持块可读，引用计数从 1 起步而非从 $G$ 起步。具体例子：一个 8K prompt、$G{=}16$ 的组，朴素路径要跑 16 次 8K 预填，共享路径只跑 1 次，剩余 15 份算力全部转给 decode 与后续组。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-15\">十五 · 显存项：$(G-1)L_p$ 的节省从哪来</h3>\n<p>显存公式给出两个对照：<span class=\"formula\">$$M_{\\text{share}}=L_p+G\\cdot L_o,\\quad M_{\\text{naive}}=G\\cdot(L_p+L_o)$$</span> 这里 $L_p$、$L_o$ 以 KV 块数计（块大小固定，例如 16 或 32 token 一块），$G$ 为组内采样数。展开 $M_{\\text{naive}}=G L_p+G L_o$，与 $M_{\\text{share}}$ 相减得节省量 $(G-1)L_p$，占朴素总量的比例接近 $(G-1)L_p/M_{\\text{naive}}$。当 $L_p\\gg L_o$（长 prompt、短生成，正是 RL rollout 的典型形态），该比例趋近 $(G-1)/G$。</p>\n<p>推导的关键一步是把 KV 占用拆成\"共享前缀 + 私有后缀\"两段而非按请求整段计：前缀段的块被 $G$ 条请求的块表同时指向，物理上只有一份；后缀段每条请求各自持有可写块，互不重叠。逐 token 的字节数由 $d_h\\cdot n_l\\cdot b$ 决定（$d_h$ 头维度、$n_l$ 层数、$b$ 每元素字节数），完整形式即 <span class=\"formula\">$$M_{\\text{KV}} = \\underbrace{L_p d_h n_l b}_{\\text{共享前缀}} + G\\cdot \\underbrace{L_o d_h n_l b}_{\\text{私有后缀}}$$</span>。注意 $b$ 在低精度档位下变小，但共享块必须保证 $G$ 条请求读到的是同一份数值——若某条请求因量化档位不同而需要不同精度的前缀，共享即失效，这是部署配方里\"共享块在低精度下 attention 数值一致\"的硬约束。</p>\n<p>代价是驻留时间被长尾拉长：前缀块的引用计数等于\"尚未结束的组内请求数\"，短样本先到 EOS 只递减计数、不释放块，必须等最长样本结束才归零。设组内最长生成长度为 $L_o^{\\max}$，则前缀块的实际驻留时间正比于 $L_o^{\\max}$ 而非均值，KV 池的有效容量按最坏情况被占用。具体例子：$G{=}8$、$L_p$ 对应 8K token 的前缀块，若组内 7 条在 200 token 内结束、1 条跑到 4K，则这 8K 前缀块在整个 4K 解码期间一直被钉住，池中可分配给其他组的块数相应减少。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-16\">十六 · 块表与引用计数：可实现的伪代码骨架</h3>\n<p>把机制落到代码，需要三个数据结构：前缀池（以 prompt 哈希或 token 序列为键，值为块 ID 列表 + 引用计数）、每请求的块表（前段指向共享块、后段指向私有块）、以及块分配器的空闲链表。伪代码思路如下，用文字描述控制流而不落成代码块：</p>\n<ul>\n<li>入组：调度器对到达请求计算 prompt 键，若前缀池命中则对该条目引用计数加 1，把其块 ID 列表拷入请求块表前段；未命中则将该请求挂入待预填队列，等凑齐同键请求或超时后单独预填。</li>\n<li>预填：对未命中的键做一次 chunked prefill，每填满一个块就登记进前缀池（引用计数初始化为当前等待该键的请求数），并把块 ID 写入这些请求的块表前段。</li>\n<li>解码步：每个 step 对组内所有未结束请求取上一 token，写各自的私有 KV 块（必要时向分配器申请新块并追加到块表后段），attention 时按块表顺序拼接\"共享前缀块 + 私有后缀块\"计算。</li>\n<li>结束：请求命中 EOS 或 max_len 时，释放其块表后段的全部私有块回空闲链表，并对前段每个共享块做引用计数减 1；计数归零的块回收到前缀池的 LRU 队列，而非直接还给空闲链表。</li>\n<li>回收：LRU 队列按\"最近被引用时间\"排序，淘汰时先检查引用计数是否为零，为零才真正释放物理块；整组结束后把 token id 与 logprob 打包送回训练侧。</li>\n</ul>\n<p>这套骨架的系统代价集中在分配器：PagedAttention 原本假设块表是请求私有的、块生命周期与请求同寿；引入跨请求共享后，分配器必须维护引用计数、支持块在多个块表间被指向、并在释放路径上做计数递减而非直接回收。碎片管理随之复杂——共享块不能按请求粒度合并或搬迁，前缀池的 LRU 队列与活跃组的共享块争抢同一片显存。具体例子：一个引用计数泄漏（某条请求异常终止未走释放路径）会让 8K 前缀块永不回收，池容量单调下降，最终新组全部退化为逐条预填。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-17\">十七 · 收益的边界条件：$L_p$ 占比与 $G$ 的取舍</h3>\n<p>把两个公式合起来看收益的敏感度。时间侧收益是 $(G-1)T_{\\text{prefill}}(L_p)$，显存侧收益是 $(G-1)L_p$ 块，两者都正比于 $L_p$ 与 $(G-1)$。因此适用边界由两个比值刻画：$L_p/(L_p+L_o)$（prompt 在单条轨迹 KV 中的占比）与 $G$。短 prompt 下 $L_p$ 占比低，节省量随之缩水；$G$ 增大则节省线性增长，但长尾驻留时间也随组内最长样本拉长——$G$ 越大，组内出现极端长样本的概率越高，前缀块的钉住时间越难预测。</p>\n<p>推导的关键一步是把\"节省\"写成相对量而非绝对量：相对显存节省 $\\approx (G-1)L_p/M_{\\text{naive}}$，当 $L_o\\to 0$ 时趋于 $(G-1)/G$；相对时间节省则取决于 $T_{\\text{prefill}}$ 在 $T_{\\text{rollout}}$ 中的原始占比（给定事实为长 prompt 下 30% 以上），共享后该占比降为原来的 $1/G$。这两个相对量共同决定是否值得引入引用计数与跨请求块表的实现复杂度。</p>\n<p>工程判断上，容量规划要按\"最坏驻留\"而非\"平均驻留\"估算池大小：若组内长度分布的重尾明显，前缀池的有效容量应按 $L_o^{\\max}$ 而非 $\\bar{L}_o$ 折算，否则会出现池被少量长尾组占满、新组排队等预填的吞吐塌陷。具体例子：同一批次里混有 8K prompt 的短生成组与 2K prompt 的长生成组，前者前缀块周转快、后者慢，若 LRU 不区分\"引用中\"与\"可淘汰\"，淘汰策略可能误回收仍在被读的前缀块，直接引发 attention 读到脏块或缺失块的错误。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-18\">十八 · 与相邻机制的公式对照</h3>\n<p>与本算法最容易混淆的是分块预填搭载解码：后者在时间维度上把 prefill 与 decode 混在同一 step 里填满 GPU，其收益项是减少空泡、提高单 step 利用率，公式上体现为把 $T_{\\text{prefill}}$ 与 $T_{\\text{decode}}$ 重叠；本算法则在空间维度上让 $G$ 条采样共享同一份 prompt KV，收益项是消除 $(G-1)$ 份重复预填与 $(G-1)L_p$ 份重复显存。两者可叠加：共享前缀把预填总量压到 1 份后，剩下的这一次预填仍可用搭载解码的方式与在途 decode 混合。与在线剪枝的对照更直接——剪枝放弃低价值轨迹、把 $G$ 变小，本算法保留全部 $G$ 条但让每条的前缀成本摊薄，前者动的是 $G$，后者动的是 $L_p$ 的系数。</p>\n<p>公式层面的一个推论：当 $G$ 因剪枝而下降时，本算法的相对收益 $(G-1)/G$ 反而变差，说明两者在同一 rollout 引擎里存在张力——剪枝越激进，前缀共享的边际价值越低；反之若前缀共享已经把预填成本压到可忽略，剪枝的动机就更多来自 decode 算力而非预填算力。这个判断决定了引擎里两个优化器的开关顺序：先做前缀共享把 $T_{\\text{prefill}}$ 项压下去，再评估剪枝对 $G\\cdot T_{\\text{decode}}$ 项的削减是否仍划算。</p>\n<p>最后落在引用计数这一具体机制上：它是整套推导能否兑现的唯一硬依赖。公式给出的 $(G-1)L_p$ 节省是上界，实际节省等于\"前缀块在被引用期间真正被 $G$ 条请求共用的小时数\"积分；引用计数泄漏、LRU 误淘汰、组未满时的提前预填，三者中任何一个都会让实际值偏离上界。工程上应把引用计数的不变量（每个共享块的计数等于指向它的活跃块表数）做成分配器的断言，并在组结束时做一次全池对账，把偏离不变量的块强制回收——这比事后调池大小更能稳住长 prompt 高 $G$ 场景下的可用容量。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-19\">十九 · 共享前缀的边界：驻留、引用与回收的三重代价</h3>\n<p>公式里那个 $(G-1)L_p$ 的节省量是静态的，真实系统里它被两个动态量侵蚀。第一个是<strong>驻留时间</strong>：前缀块的生命周期不取决于最早结束的样本，而取决于组内最长样本。设组内第 $i$ 条采样长度为 $L_o^{(i)}$，前缀块的显存占用时间为 $\\max_i T_{\\text{decode}}(L_o^{(i)})$，而它承载的有效计算只有一次预填。于是前缀块的“显存效率”可写成</p>\n<div class=\"formula\">$$\\eta_p=\\frac{L_p}{\\max_i L_o^{(i)}\\cdot G}\\quad\\text{（单位显存·时间的产出）}$$</div>\n<p>当组内长度分布方差大——RL rollout 里极常见，因为同一 prompt 的 G 条轨迹会因采样温度而长短悬殊——$\\max_i L_o^{(i)}$ 远高于均值，$\\eta_p$ 被长尾拉低。极端情况下短样本在几十个 token 后就 EOS，前缀块却要陪最长样本跑到 max_len，KV 池的实际可用容量低于按 $L_p+G\\cdot L_o$ 估算的账面值。这是本方案最本质的失效条件：<strong>节省量随 $G$ 线性增长，驻留惩罚却随长度方差超线性增长</strong>，两者在某个 $G$ 处交叉，超过这个点共享反而比朴素方案更早触发 OOM。</p>\n<p>第二个代价在块分配器。跨请求共享要求 PagedAttention 的块表从“一对一所有权”变成“多对一引用”，每个前缀块带一个引用计数，块表前段存的是共享块的逻辑块号而非物理块号，attention kernel 读 KV 时必须先做一次块表拼接再寻址。伪代码落到可实现层面大致是：</p>\n<ul>\n<li>prefill 阶段：<code>prefix_blocks = alloc(L_p); ref_cnt[prefix_blocks] = G</code>，一次 chunked prefill 写入后登记进前缀池，键为 prompt token id 的哈希；</li>\n<li>decode 阶段：每条采样 <code>private = alloc(L_o)</code>，块表 <code>bt = concat(prefix_blocks, private)</code>，每步只写 <code>private[step]</code>，attention 按 <code>bt</code> 拼接寻址；</li>\n<li>结束阶段：<code>free(private); ref_cnt[prefix_blocks] -= 1; if ref_cnt == 0: recycle(prefix_blocks)</code>。</li>\n</ul>\n<p>这段伪代码的风险点不在主路径，在异常路径。引用计数泄漏——某条采样因调度器抢占、请求取消或异常退出而未走到递减分支——会让前缀块永不归零，KV 池被逐步蚕食且不报错，表现为吞吐缓慢下滑而非崩溃，是最难定位的一类故障。工程上必须把递减动作绑在请求生命周期的统一析构点上，而不是散落在 EOS 与 max_len 两个分支里。</p>\n<p>第三个代价是 LRU 与引用中的块争抢。前缀池按 LRU 保留热点 prompt 供下一轮复用，但“热点”与“正在被引用”是两个正交属性：一个块可能引用计数为正却因长时间未被新请求命中而排在 LRU 队尾。淘汰策略若不显式排除 <code>ref_cnt &gt; 0</code> 的块，就会误回收仍在被 G 条采样读取的前缀，attention 读到已覆写的物理块，输出静默错误。正确做法是 LRU 队列只挂 <code>ref_cnt == 0</code> 的空闲块，引用中的块从候选集中摘除，代价是池的有效容量进一步缩水。此外共享块在低精度量化下被 G 条采样同时读取，必须保证同一份 KV 的数值一致性——量化档位未给出，但共享语义要求前缀块只做一次量化写入、所有读者读同一份位模式，不能按请求各自反量化。</p>\n<table class=\"mini\"><thead><tr><th>代价项</th><th>触发条件</th><th>系统表现</th></tr></thead><tbody><tr><td>长尾驻留</td><td>组内长度方差大</td><td>KV 池可用容量低于账面值，提前 OOM</td></tr><tr><td>引用计数泄漏</td><td>异常路径未析构</td><td>吞吐缓慢下滑，无显式报错</td></tr><tr><td>LRU 误回收</td><td>淘汰未排除引用中块</td><td>attention 读脏块，输出静默错误</td></tr></tbody></table>\n<p>由此给出规模上限的工程判断：$G$ 的选取不能只看 $(G-1)L_p$ 的节省曲线，要把组内长度分布的 P99 与均值之比作为约束项——该比值越高，前缀块驻留惩罚越重，$G$ 应相应压小；同时块分配器的引用计数开销随并发组数线性上升，组数过多时元数据本身成为瓶颈。适用边界因此收窄为：同一 prompt 多采样、长 prompt 占比高、且组内长度分布相对集中的 RL rollout 场景；长度分布离散度大的任务，应先在采样侧做长度对齐或分组重排，再谈共享。</p>\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-20\">二十 · 请求形态：G 条同源采样的“组”才是调度单元</h3>\n<p>前缀 KV 共享的收益不来自单条请求变快，而来自“组”这一调度粒度的成立。负载配方第一条硬约束：请求必须能成组。RL 后训练里同一 prompt 采样 G 条轨迹是天然成组的，但推理服务侧的流量往往不是——线上对话每个请求 prompt 各不相同，前缀池命中率取决于系统提示与多轮历史的公共前缀，而非同源采样。把共享机制套到不同源请求上，前缀块引用计数只会被不同 prompt 的块表零散引用，节省量退化为偶发命中，而块分配器的引用计数开销照付。因此判断负载是否适配，先看“同 prompt 的 G 条请求能否在时间窗内同时在引擎内驻留”：若采样侧把 G 条请求拆散到不同批次、不同时刻提交，先到的采样已经把 prompt 预填做完并进入 decode，后到的采样再走一次预填，共享窗口就被错过。工程上要求采样侧按 rollout group 成批提交，调度器按 prompt 分组绑定，组内 G 条请求共享一次 chunked prefill 的产物。</p>\n<p>组内并发的排布直接决定 decode 阶段的批形状。G 条采样以 continuous batching 并行推进，每步只为各自新 token 写私有 KV 块，attention 按块表拼接共享前缀与私有后缀。批大小因此不是自由参数，而是被组结构约束：一个 rollout group 贡献 G 条序列，引擎的批由若干组拼成，批内序列长度参差。若 G 很大（数十条），单组就能填满一个 decode 批，批内长度分布由该 prompt 的采样发散度决定；若 G 很小，需要多组合批才能打满 SM，此时不同组的前缀块同时在读，前缀池的驻留压力按组数线性叠加。负载配方的核心判断是：G 与组数的乘积决定并发序列数，而前缀池容量决定这些序列能同时驻留多少组。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-21\">二十一 · 长度分布：L_p 占比决定收益，L_o 长尾决定驻留</h3>\n<p>收益侧的公式是显存对比：</p>\n<div class=\"formula\">$$M_{\\text{share}}=L_p+G\\cdot L_o,\\quad M_{\\text{naive}}=G\\cdot(L_p+L_o)$$</div>\n<p>节省量为 $(G-1)L_p$，占朴素方案的比例接近 $(G-1)L_p/M_{\\text{naive}}$。这个式子说明收益完全由 $L_p$ 在总 KV 中的占比决定：prompt 越长、采样后缀越短，共享越值钱；prompt 很短而采样很长（例如短指令触发长思维链），$L_p$ 被 $G\\cdot L_o$ 淹没，节省量趋近于零，而引用计数与块表拼接的复杂度照付。因此负载配方要求长度分布呈“长前缀、相对短后缀”形态——长 prompt（8K 以上）下预填算力占 rollout 总 FLOPs 的 30% 以上，正是这类形态让一次预填替代 G 次预填的价值成立；短 prompt 场景收益随 $L_p$ 占比下降，属于不该开启共享的区间。</p>\n<p>驻留侧的矛盾在 $L_o$ 的分布而非均值。前缀块被组内 G 条采样共享读，某条采样结束（EOS 或 max_len）只释放其私有块并递减引用计数，前缀块要等引用归零才回收。若组内采样长度差异大，短样本早早结束却无法释放前缀块，必须等最长样本结束，显存驻留时间被长尾拉长。这意味着前缀池的实际可用容量低于按平均长度估算的值：一批组里只要每组都有一条长尾样本，前缀块的实际占用时长由该组长尾决定，池的有效周转率下降。负载配方的第二条判断是看组内长度方差——方差小，前缀块随组整体释放，池周转干净；方差大，前缀池被长尾钉住，新组进不来，调度器只能降低并发组数，吞吐反而下降。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-22\">二十二 · 并发与批大小：前缀池容量反推可驻留组数</h3>\n<p>把两件事拼起来可以得到容量规划的粗粒度关系：设前缀池可容纳的 KV 块数为 $C$，单组前缀块 $L_p$、组内私有块峰值 $G\\cdot L_o^{\\max}$，则同时驻留的组数 $N_g$ 受</p>\n<div class=\"formula\">$$N_g \\le \\frac{C}{L_p + G\\cdot L_o^{\\max}}$$</div>\n<p>约束。分母里 $L_o^{\\max}$ 取组内最长样本而非平均，因为长尾样本的私有块一直占到它结束。这个不等式解释了为什么 G 增大不是单调利好：节省量 $(G-1)L_p$ 随 G 增长，但分母中的 $G\\cdot L_o^{\\max}$ 同步增长，且长尾驻留随 G 增大而更严重（G 越大，组内出现极端长样本的概率越高）。存在一个由长度分布决定的 G 区间，超过后前缀池周转不过来，decode 批被迫缩小，吞吐掉头向下。工程上应把 G 作为可调参数按 prompt 长度分档：长 prompt 用较大 G 摊薄预填，短 prompt 用小 G 甚至不分组，避免为微小节省付出长尾驻留。</p>\n<p>批大小的另一个约束来自块表拼接的读放大。decode 每步 attention 要按块表把共享前缀块与私有后缀块拼成逻辑序列，前缀块被 G 条序列同时读，单步读带宽里前缀部分被放大 G 倍。前缀越长、G 越大，每步 decode 的有效 KV 读量越接近 $G\\cdot L_p$ 的量级，而计算只增加 G 条新 token 的增量。这在带宽受限的 decode 阶段会表现为每步时延随 G 上升，抵消了预填节省带来的端到端收益。负载配方因此要求 decode 阶段的带宽预算按“共享前缀读放大”重新核算，而不是沿用单序列的 KV 读量估算。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-23\">二十三 · 负载不对时的三种塌陷</h3>\n<p>第一种是短前缀塌陷。prompt 短、采样长，$L_p$ 占比低，预填本就不是瓶颈，共享带来的 FLOPs 节省可忽略，而块分配器要为每条采样维护跨请求引用的块表，碎片管理成本上升，端到端时延不降反升。判断信号是预填时间在 rollout 总时延中的占比：占比低时共享是纯开销。</p>\n<p>第二种是长尾驻留塌陷。组内长短样本差异大，短样本结束后前缀块仍被最长样本引用，KV 池实际可用容量低于预期，调度器观察到池满却无法回收，只能阻塞新组进入。表现为吞吐随负载上升而饱和甚至回落，而单组时延看起来正常。缓解手段是给组内采样设长度上限或按长度分桶成组，把方差压小；但分桶会削弱“同 prompt 一次预填”的成组前提，需要在采样侧配合。</p>\n<p>第三种是引用计数泄漏。块表跨请求共享使引用计数与碎片管理复杂化，任何一条路径漏减引用（异常终止、抢占重调度、组内请求被取消）都会让前缀块永不回收，KV 池逐步耗尽。这类故障不报错，只表现为池容量单调下降。工程上需要把引用计数与请求生命周期绑定做审计，并在池水位超过阈值时强制扫描引用中块。另一类相关错误是 LRU 淘汰与在用块争抢：LRU 保留热点前缀供下一轮复用，若淘汰策略未区分引用中块，可能误回收仍在读的前缀块，引发 attention 读到被覆写数据。淘汰器必须只从引用计数为零的块中选 victim。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-24\">二十四 · 配方落地：按 prompt 长度分档的参数表</h3>\n<p>把上述判断整理成可执行的配方，核心是三个按 $L_p$ 分档的决策：是否成组共享、G 的上限、组内长度方差容忍度。</p>\n<table class=\"mini\"><thead><tr><th>prompt 长度档</th><th>是否共享</th><th>G 取向</th><th>主要风险</th></tr></thead><tbody><tr><td>短（$L_p$ 占比低）</td><td>不分组，直接逐条预填</td><td>—</td><td>共享只增加块表复杂度</td></tr><tr><td>中（预填占比可观）</td><td>成组共享，G 适中</td><td>按池容量反推</td><td>组内方差拉长驻留</td></tr><tr><td>长（8K 以上，预填占比 30%+）</td><td>成组共享，收益最大</td><td>较大 G 摊薄预填</td><td>长尾驻留与读放大</td></tr></tbody></table>\n<p>分档之外还要给调度器一个组级准入条件：新组进入前检查 $L_p+G\\cdot L_o^{\\max}$ 是否放得下，放不下则等待或拆组；组内某条采样超过预设长度阈值时提前截断，避免单条长尾钉住整组前缀块。这些规则不改变共享机制本身，只是把负载形态约束翻译成调度参数。</p>\n<p>最后落在工程判断上：前缀 KV 共享的收益函数是 $(G-1)L_p$ 减去长尾驻留与引用计数开销，前者由长度分布决定，后者由组内方差与实现质量决定。负载配方的工作不是调大 G，而是先把请求形态压成“同源、长前缀、低方差”的组，再让 G 和批大小在这个形态内取值；形态不对时，正确动作是关闭共享或改采样侧的分组方式，而不是在引擎里加缓存层数硬扛。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-25\">二十五 · 负载配方：什么请求形态才配得上共享前缀池</h3>\n<p>这套机制的经济性完全由负载形态决定，判据只有一个：共享前缀的 KV 体量是否压得过私有后缀与长尾驻留。用块数表示，共享方案占用 $M_{\\text{share}}=L_p+G\\cdot L_o$，朴素方案为 $M_{\\text{naive}}=G\\cdot(L_p+L_o)$，节省量恰为 $(G-1)L_p$。把它写成占比更直观：$\\rho=(G-1)L_p/\\big(G(L_p+L_o)\\big)$，当 $L_p\\gg L_o$ 时 $\\rho\\to(G-1)/G$，而当 $L_p$ 与 $L_o$ 同量级、$G$ 又小（例如 G=4、$L_p=L_o$）时 $\\rho$ 只有 0.375，收益被私有后缀稀释。所以配方第一条是：prompt 长度分布必须长尾偏重、且 8K 以上长 prompt 在 batch 中占实质比例——正是这类负载下预填算力才会占到 rollout 总 FLOPs 的 30% 以上，共享才把 $T_{\\text{prefill}}(L_p)$ 从 G 次压成 1 次，$T_{\\text{rollout}}\\approx T_{\\text{prefill}}(L_p)+G\\cdot T_{\\text{decode}}(L_o)$ 中的第一项近似降为 1/G。第二条是组内同质性：$L_o$ 的方差决定前缀块驻留时间，方差越大，显存周转越差。</p>\n<p>并发与批大小的组织方式与前缀池的粒度强耦合。调度器按 prompt 分组、把同一 prompt 的 G 条请求绑成一个 rollout group，批不是按请求条数凑，而是按 group 凑：一个 group 内 G 条采样以 continuous batching 并行推进，每步只写各自新 token 的 KV。这意味着有效批大小约为 $B_{\\text{eff}}\\approx N_{\\text{group}}\\cdot G$，而显存需求近似 $N_{\\text{group}}\\cdot(L_p+G\\cdot L_o)$。工程判断是：G 增大时单位 prompt 的显存边际成本从 $L_p+L_o$ 降到 $L_o$，但组数 $N_{\\text{group}}$ 受前缀池容量约束——池子里同时驻留的 prompt 前缀块越多，可用于私有后缀与生成长尾的余量越少。短 prompt、低 G、高并发的负载（例如大量独立短问答）不该走这条路：$L_p$ 小到共享块本身只占几块，引用计数与块表拼接的调度开销反而成为主项。</p>\n<p>负载不对时的失效是结构性的，不是调参能救的。最典型的是组内长短样本差异大：短样本先到 EOS 也无法释放前缀块，因为引用计数仍被最长样本持有，前缀块驻留时间被长尾拉长，KV 池实际可用容量低于按平均长度估算的预期，表现为吞吐在长尾组上塌陷、后续 group 排队等块。其次是引用计数泄漏——块表跨请求共享后，分配器必须支持引用计数与跨请求共享，任何一条路径漏减计数，前缀块永不回收，池子逐步耗尽且症状隐蔽（显存缓慢爬升而非报错）。第三是 LRU 保留热点前缀与当前活跃组争抢显存：若淘汰策略不区分“引用中”与“空闲”块，可能误回收仍在被读的前缀块，attention 按块表拼接时读到已覆写数据，输出错乱而非崩溃，这类错误在 RL rollout 里会直接污染训练信号。可用一张小表把边界钉住：</p>\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>共享收益</th><th>主要代价</th></tr></thead><tbody><tr><td>长 prompt（8K+）占比高、组内 $L_o$ 集中</td><td>预填近似 1/G，显存省 $(G-1)L_p$</td><td>前缀池容量与引用计数开销</td></tr><tr><td>长 prompt 但组内 $L_o$ 方差大</td><td>预填仍省，显存省被长尾吃掉</td><td>前缀块驻留被最长样本拉长</td></tr><tr><td>短 prompt、G 小、请求彼此独立</td><td>接近零</td><td>块表拼接与计数管理纯开销</td></tr></tbody></table>\n<p>因此规模上限由两个量共同约束：组内最长样本的驻留时间（决定池子周转率）与块分配器引用计数的每块管理开销（决定单位显存能挂多少共享引用）。G 越大节省越多，但长尾驻留越严重，二者不是单调权衡，需要按 $L_o$ 的分位数而非均值来做容量规划——按均值配池必然在长尾组上过载。另一个必须守住的边界是数值一致性：共享块被 G 条采样共同读取，若前缀 KV 以低精度存储，所有采样看到的是同一份量化误差，attention 数值必须在共享路径与私有路径间保持一致，否则组内轨迹的可比性被破坏，而这一点在量化档位未定时只能靠固定共享块的存储精度来保证。</p>\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-26\">二十六 · 硬件档位与前缀池的驻留预算</h3>\n<p>前缀KV共享的部署起点不是“选哪张卡”，而是先算清楚前缀池要占多少显存。由 $M_{\\text{share}}=L_p+G\\cdot L_o$ 与 $M_{\\text{naive}}=G\\cdot(L_p+L_o)$ 可知，节省量固定为 $(G-1)L_p$，但这份节省是“账面”的：前缀块在组内最长样本结束前不能被回收，因此实际驻留预算必须按 $G\\cdot L_o^{\\max}+L_p$ 来留，而不是按平均长度 $L_o$ 来留。工程判断是：把前缀池容量按“当前活跃组数 × 组内最长样本私有块峰值”反推，再额外留出LRU热点前缀的空间，否则池子会在长尾组上被顶死。硬件档位上，B200/B300 单卡HBM容量决定了单机可容纳的活跃组数；GB200/GB300 NVL72 的价值在于把前缀池做成跨节点可寻址的共享层——同一prompt的G条采样若被调度到不同节点，前缀块必须能被远端读取，否则共享退化为复制。这里不展开池化传输细节（见KV中心分离式池化条目），只强调一点：前缀池的物理位置决定了并行拓扑的下限。</p>\n<p>一个具体例子：8K prompt、G=8、每条约1K输出，若 $d_h n_l b$ 折算后单条私有后缀占若干块，则naive方案下该组KV是共享方案的数倍；把G条采样全部压在一张卡上，前缀池只需一份，但私有块峰值是 $8\\times L_o^{\\max}$，卡容量必须覆盖这个峰值而非平均值。若卡容量不够，正确做法是把组拆到两个节点、让前缀块跨节点共享读，而不是退化成每节点各存一份前缀——后者直接把 $(G-1)L_p$ 的节省吐回去。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-27\">二十七 · 并行拓扑：组内并行与组间并行的取舍</h3>\n<p>rollout group 是调度的原子单位，但“原子”不等于“同卡”。拓扑设计要回答两个问题：组内G条采样是否必须落在同一TP/EP域内，组间如何填满剩余算力。组内采样的decode步长相近、共享同一前缀块表，放在同一continuous batching批次里推进最省调度开销，attention读取共享前缀时也只需一次块表拼接；代价是组内最长样本会拖住整个组的批次槽位。组间并行则用来吸收长尾：当一个组因长样本驻留而占用前缀块时，其他组继续用私有块填批，维持decode吞吐。工程上常见的配方是“组内同TP域、组间跨DP副本”，让前缀池在DP副本间以引用计数共享，而不是每个副本独立预填。这样做的系统代价是跨副本的块表一致性维护——引用计数必须在共享池层面原子更新，否则泄漏会让前缀块永不回收。</p>\n<div class=\"formula\">$$\\text{批内槽位占用} \\approx \\sum_{g\\in\\text{active}} G_g,\\quad \\text{前缀池占用} \\approx \\sum_{g} L_{p,g}\\cdot \\mathbb{1}[\\text{ref}(g)&gt;0]$$</div>\n<p>公式含义：批内槽位按组累加，前缀池占用只统计引用计数非零的组。调度参数上，应把“组内最长样本剩余步数”作为组优先级的一部分，短样本结束后其私有块立即释放、槽位让给其他组，但前缀块继续驻留——这正是长尾驻留的来源，也是拓扑必须留出组间并行余量的原因。若把所有活跃组都塞进一个TP域，长尾组会同时占用前缀块和槽位，吞吐被双向挤压。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-28\">二十八 · 量化方案：共享块的低精度一致性约束</h3>\n<p>前缀块被G条采样共享读，量化档位的选择不再是单请求的精度-吞吐权衡，而是“一份共享块必须对所有读者数值一致”。NVFP4/FP8 的量化误差在共享前缀上只发生一次，却会被G条采样的attention同时消费；若前缀块与私有后缀块采用不同量化档位，attention在拼接时要做尺度对齐，拼接点的数值跳变会放大采样分布的偏移。部署配方因此倾向于：前缀块与私有块使用同一量化档位，且前缀块的量化尺度在写入时固定、不做逐组重算，保证引用期间尺度稳定。系统代价是：低精度前缀块减少了 $L_p$ 的显存占用，直接放大 $(G-1)L_p$ 的节省比例，但若为了数值一致而把私有块也锁在同一档位，decode阶段的量化灵活性被牺牲。工程判断是长prompt占比高时优先统一档位换显存，短prompt占比高时允许私有块用更激进的档位。</p>\n<p>具体机制上，块表引用共享前缀时，attention kernel 需要按块粒度读取量化尺度；若前缀块被LRU保留跨轮复用，其尺度必须随块一起持久化，不能在新一轮重新校准。失败模式是：某条采样结束后前缀块引用递减但未归零，此时若调度器触发重校准，仍在读的采样会看到尺度漂移。因此量化方案必须与引用计数生命周期绑定——尺度只在引用归零、块回收到池后才可以重写。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-29\">二十九 · KV策略：LRU热点保留与引用中块的隔离</h3>\n<p>前缀池的淘汰策略是本部署配方最容易出错的一环。LRU保留热点prompt前缀供下一轮复用，能省掉跨轮重复预填；但当前组仍在引用的前缀块绝不能进入淘汰候选。配方上应把池分为两层：引用计数大于零的“活跃层”只增不减，引用归零的块进入“候补层”按LRU排序，候补层容量按热点命中率与显存余量调参。系统代价是候补层占用的显存直接压缩了活跃组的私有块峰值空间，长尾组多的时候候补层必须主动收缩，否则会出现“热点前缀挤掉活跃组私有块”的倒挂。</p>\n<p>另一个策略点是私有块的分配粒度。G条采样的私有后缀长度差异大，若按固定大块分配，短样本会浪费；若按细粒度分页，块表项变多、引用计数管理开销上升。工程折中是：前缀块用大粒度（减少引用计数对象数），私有块用细粒度（吸收长度方差）。这样引用计数的操作次数与前缀块数成正比而非与总块数成正比，把跨请求共享的实现复杂度压在可控范围内。伪代码思路：<em>alloc_prefix(prompt) → refcount=1；for each sample: block_table = [prefix_blocks] + alloc_private(); on EOS: free_private(); refcount-=1；if refcount==0: move_to_lru_candidate()</em>。注意 free_private 与 refcount 递减的顺序不能颠倒，否则会出现块表仍指向前缀而计数已归零的窗口。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-30\">三十 · 调度参数：以组为单位的准入与长尾定价</h3>\n<p>调度器按prompt分组绑定rollout group，准入控制应以“组所需前缀块 + G条私有块峰值”为资源申请量，而不是按单请求估算。参数上需要三个旋钮：组内最大G（G越大节省越多但长尾驻留越严重）、单组私有块峰值上限（超过则拆组或延后准入）、前缀池候补层水位（低于阈值时暂停新组预填，优先消化存量）。系统代价体现在预填时间上：$T_{\\text{rollout}}\\approx T_{\\text{prefill}}(L_p)+G\\cdot T_{\\text{decode}}(L_o)$，预填只做一次使长prompt场景预填时间近似降为 $1/G$，但若准入把多个长prompt组同时放进来，前缀池瞬间被 $L_p$ 填满，后续组的预填被迫排队，decode吞吐反而下降。</p>\n<p>具体例子：8K以上prompt占比高的负载，预填算力占rollout总FLOPs的30%以上，调度应优先保证这些组的预填一次完成并登记入池，再让它们的G条采样以continuous batching推进；短prompt组则允许更激进的G和更小的私有块上限，因为 $L_p$ 占比低、共享收益小。长尾定价的做法是给每个组的“最长样本剩余步数”乘一个权重计入批次优先级，让长尾组占用前缀块的成本被显式计入调度决策，而不是隐式地拖垮整批。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-31\">三十一 · 可复现的配置思路：从负载画像到参数落位</h3>\n<p>给出一套可复现的配置推导顺序，不依赖具体硬件型号数字。第一步，采集负载画像：prompt长度分布、G分布、输出长度方差，算出 $L_p$ 占比与 $(G-1)L_p/M_{\\text{naive}}$ 的期望节省。第二步，按最长样本峰值定前缀池容量与单组私有块上限，反推单机可容纳活跃组数，决定是否需要跨节点共享前缀。第三步，定并行拓扑：组内同TP域、组间跨DP副本，前缀池引用计数在共享层原子维护。第四步，定量化档位：前缀块与私有块统一档位优先，尺度随块持久化、只在引用归零后重写。第五步，定调度参数：组准入按峰值资源申请、候补层水位、长尾权重，并用引用计数泄漏检测作为上线前的必测项——构造长短样本差异大的组，验证短样本结束后前缀块仍被引用、长样本结束后引用归零回收、LRU不误回收活跃块三条路径。系统代价的验收口径是：预填时间是否接近 $1/G$、前缀池实际可用容量是否被长尾拉低到预期以下、块分配器引用计数开销是否吃掉了decode吞吐增益。三条中任一不达标，优先调组准入与候补层水位，而不是调G。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-32\">三十二 · 部署配方的边界条件：从“省”到“稳”的四个失效面</h3>\n<p>前缀共享的收益不是无条件兑现的，它的部署配方必须围绕四个失效面来定档。第一是<strong>组内长度离散度</strong>：前缀块的引用计数由组内最长样本决定，短样本 EOS 后私有块释放、前缀块引用减一但计数不归零，驻留时间被长尾拉长。设组内最长私有后缀为 $L_o^{\\max}$，则前缀块的实际驻留代价按 $L_p+G\\cdot L_o^{\\max}$ 计而非按均值计——这意味着调度参数里的 <code>max_len</code> 与组内长度分布直接决定 KV 池的有效容量，G 越大、长尾越长，池子被“钉住”的比例越高。配方上应把同一 prompt 的 G 条采样绑定为同一 rollout group 后，对组内长度做预估分档，把长度方差大的组拆小 G 或单独排队，避免一条超长样本拖住整组前缀块。</p>\n<p>第二是<strong>块分配器的引用计数正确性</strong>。跨请求共享块表要求 PagedAttention 分配器支持引用计数、跨组共享与碎片回收，任何一次计数泄漏都会让前缀块永不回收，KV 池逐步耗尽且表现为“容量缓慢下降、无明显报错”。工程上必须把引用计数做成可观测指标（每块的 refcount 分布、归零回收速率、池内驻留块年龄直方图），并设置强制回收兜底：当池水位超过阈值时，对 refcount 长期不降的块做审计而非静默淘汰。第三是<strong>LRU 与在引用块的冲突</strong>：LRU 保留热点前缀供下一轮复用，但若淘汰策略不区分“引用中”与“空闲”块，可能误回收仍在被 G 条采样读取的前缀块，引发 attention 读到已释放块的数据错误。配方上必须把 LRU 候选集限定为 refcount 为零的块，热点保留与当前组共享块分属两个池区，物理隔离。</p>\n<p>第四是<strong>低精度共享块的数值一致性</strong>。量化档位未给出，但共享块被 G 条采样同时读取，任何对前缀 KV 的低精度量化（如 FP8/NVFP4 存储）必须保证同一块在多次 attention 读取中数值一致，不能因分叉写入或块表拼接引入精度抖动；私有后缀块与共享前缀块若采用不同量化档位，拼接处的 attention 数值偏差会被 G 条轨迹放大，影响 logprob 打包回训练侧的可信度。配方判断：前缀块与私有块应使用同一 KV 量化档位，共享块只读、私有块可写，量化参数在块粒度上固定。系统代价上，引用计数与跨组块表使分配器元数据开销上升，碎片管理成本随 G 与并发组数增长；收益侧仍由 $M_{\\text{share}}=L_p+G\\cdot L_o$ 对 $M_{\\text{naive}}=G\\cdot(L_p+L_o)$ 的 $(G-1)L_p$ 节省支撑，但只有当长尾驻留与引用开销被上述配方压住时，这部分节省才真正转化为可用显存与预填时间下降。</p>\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-33\">三十三 · 显存驻留时间：被长尾钉住的前缀块</h3>\n<p>前缀KV共享把显存占用从 $G\\cdot(L_p+L_o)$ 压到 $L_p+G\\cdot L_o$，节省量 $(G-1)L_p$ 在长prompt下占比接近 $(G-1)L_p/M_{\\text{naive}}$。但这是**瞬时占用**的账，不是**驻留时间**的账。前缀块的释放条件是引用计数归零，而组内G条采样的结束时刻由各自的EOS或max_len决定，长度分布天然右偏。短样本在 $L_o$ 较小处就结束，释放的只是自己的私有块；前缀块仍被最长样本引用，必须等它跑完。于是前缀块的显存驻留时间被拉长为组内最长样本的decode时长，而非平均时长。</p>\n<p>把这点写成代价：设组内最长样本的decode步数为 $G\\cdot T_{\\text{decode}}(L_o^{\\max})$，前缀块在这整段时间内不可回收。若调度器按平均长度估算KV池容量，实际可用容量会被系统性高估。工程上的直接后果是：一个rollout group在尾段占用 $L_p$ 的共享块加上一条私有块序列，却只推进一条采样的decode，SM利用率与显存周转率同时掉下来。这就是规模上去以后第一个崩的地方——不是算力，不是带宽，是**显存的有效周转率**。</p>\n<p>具体例子：8K prompt、G=8、组内长度从数百token到数千token不等。前7条在decode早期陆续结束，前缀块的引用计数停在1，$L_p$ 对应的共享块被一条长尾采样独占持有，直到它触及max_len。此时池内可分配块数下降，后续prompt组的前缀预填被迫排队，预填吞吐塌陷。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-34\">三十四 · 带宽：共享读放大与块表拼接的间接成本</h3>\n<p>共享前缀省掉的是预填FLOPs，但decode阶段每一步的attention都要读整段前缀KV。G条采样在同一decode step里各自对同一份 $L_p$ 前缀做attention，读的是同一批块——这在理想情况下是L2与HBM的自然复用，但前提是这G条请求被continuous batching排进同一个micro-batch、且块表拼接后的地址布局对缓存友好。一旦组内采样被调度器拆到不同batch、不同step，同一份前缀块就被反复从HBM拉取，读带宽按拆分次数放大。</p>\n<p>代价可以写成每decode step的前缀读量：$B_{\\text{read}} \\approx G \\cdot L_p d_h n_l b$（未命中缓存时），而共享生效时理想值为 $L_p d_h n_l b$。分页块表的间接寻址进一步恶化这一点——attention kernel按块表拼接共享前缀与私有后缀，前缀段是只读的、后缀段是追加写的，两段在物理页上不连续，向量化加载的粒度被打断。长prompt下前缀段占KV读量的大头，块表跳转带来的额外地址计算与不连续访问，会把有效带宽压低到标称值以下。</p>\n<p>工程判断：把同一rollout group的G条采样尽量绑在同一调度批次内推进，是让共享读真正落到缓存里的前提；组被拆散时，共享只剩显存收益，带宽收益归零。这也是为什么前缀池的收益在长prompt、高G、紧绑定调度三者同时成立时才显著。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-35\">三十五 · 通信：跨组引用与池化边界的张力</h3>\n<p>前缀KV池在单引擎内是本地块表引用，代价是分配器复杂度；一旦把池扩展到分离式部署或KV中心池化，共享块就要跨进程、跨节点被引用，通信代价立刻显形。同一prompt的G条采样若分布在不同推理实例上，前缀块要么复制G份（回到naive的显存膨胀），要么通过NIXL一类传输层远程读取——后者把每步attention的前缀读变成网络往返，NVLink 5域内尚可承受，跨节点则直接吃掉decode的步进预算。</p>\n<div class=\"formula\">$$T_{\\text{step}} \\approx \\max\\left(T_{\\text{attn}}^{\\text{local}},\\ T_{\\text{fetch}}^{\\text{prefix}} + T_{\\text{attn}}^{\\text{suffix}}\\right)$$</div>\n<p>含义很直接：远程前缀取回时间一旦超过本地attention时间，decode就被通信钉住。规模上去后，rollout group的G条采样往往因为负载均衡被散到多实例，跨组引用从\"可选优化\"变成\"必经路径\"，通信成为第二个崩点。可行的收敛方向是把同prompt的G条采样做亲和性调度，绑在同一NVLink域内，让前缀块只在域内共享；跨域只传token id与logprob这类小载荷。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-36\">三十六 · 功耗与SLO：预填塌缩后的尾延迟结构</h3>\n<p>预填FLOPs从G次降为1次，rollout预填时间近似降为 $1/G$，这对SLO是巨大利好——但收益不是均匀分布的。预填阶段是功耗与算力密集段，塌缩后整组rollout的功耗曲线从\"每步都重预填\"变成\"一次预填+长decode\"，峰值功耗下降、占空比拉长。真正的风险在尾延迟：前缀块被长尾样本钉住，导致后续组的预填无法及时拿到块，预填排队时间进入尾延迟；同时长尾样本自身在组内独占共享块做单条decode，SM占用低、步进慢，进一步拉长尾。</p>\n<p>尾延迟的构成可以拆成三段：前缀块等待（池满时的排队）、组内最长样本的decode拖尾、以及引用计数回收的滞后。前两段随G增大而恶化——G越大节省越多，但长尾驻留越严重，这是本算法规模上限的核心约束，具体上限未给出。SLO以预填时间近似降为 $1/G$ 为目标时，必须同时给尾延迟设独立预算，否则平均预填时间达标而P99被长尾拖垮。</p>\n<p>具体例子：连续批处理下，一个组的长尾样本与下一组的预填争抢同一批SM。若调度器按FCFS推进，长尾样本的低占用decode会长期占据batch槽位，新组预填被推迟，P99预填延迟上升，而池内空闲块明明足够——瓶颈不在容量，在调度优先级。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-37\">三十七 · 引用计数与碎片：规模上去后的隐性泄漏</h3>\n<p>块表跨请求共享要求PagedAttention块分配器支持引用计数与跨请求共享，实现复杂度与碎片管理成本上升。规模上去后，两类失败模式会先于性能瓶颈暴露。其一是引用计数泄漏：某条采样异常终止（超时、取消、EOS路径未走完释放逻辑）时私有块释放但前缀块计数未递减，前缀块永不回收，KV池逐步耗尽——表现为池容量单调下降、预填排队变长，而监控上看不到明显的显存峰值。其二是LRU淘汰与引用中块争抢：前缀池按LRU保留热点prompt前缀供下一轮复用，若淘汰策略未区分\"引用中\"与\"空闲\"块，可能误回收仍在被G条采样读取的前缀块，引发attention读到错误KV的数值错误，这类错误在低精度共享块下更难察觉。</p>\n<p>碎片问题的根源是共享块与私有块的生命周期不同步：前缀块按prompt组批量分配、按最长样本释放；私有块按单条采样分配、按各自EOS释放。两种粒度混在同一分配器里，空闲块被切碎，大块预填找不到连续页。规模上去后，碎片导致的分配失败会比显存真耗尽更早出现。</p>\n<p>工程判断：引用计数需要与请求生命周期强绑定（取消路径必须走同一释放函数），LRU淘汰必须跳过计数大于零的块，块分配器要为共享块与私有块设不同的页粒度或预留区，避免生命周期错配把池切碎。这三条不做，G越大、prompt越长，池的可用容量越偏离账面值——这是本算法在规模上最先崩、也最难从指标上定位的地方。</p>\n\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-38\">三十八 · 前缀池的规模拐点：显存驻留、块表开销与长尾如何吃掉收益</h3>\n<p>前缀共享把显存账从 $G\\cdot(L_p+L_o)$ 压到 $L_p+G\\cdot L_o$，节省量 $(G-1)L_p$ 在长 prompt 下接近 $M_{\\text{naive}}$ 的绝大部分，但这份节省是“账面容量”，不是“可用容量”。真正的约束来自驻留时间：前缀块被组内 G 条采样共同引用，引用计数归零前不可回收，而组内采样长度服从重尾分布——少数轨迹跑到 max_len，多数早早 EOS。设组内最长样本的私有后缀长度为 $L_o^{\\max}$、中位数为 $L_o^{\\text{med}}$，则前缀块的实际占用时间为 $T_{\\text{dwell}}\\approx T_{\\text{prefill}}(L_p)+G\\cdot T_{\\text{decode}}(L_o^{\\max})$，而这段时间里它贡献的有效 token 吞吐只对应中位长度。定义驻留放大因子 $\\rho=L_o^{\\max}/L_o^{\\text{med}}$，KV 池的有效容量近似按 $1/\\rho$ 折算：G 越大、$\\rho$ 越大，池子越像被少数长尾请求“钉住”。工程上的直接后果是并发组数上不去——不是块不够，而是块被引用着不能动。</p>\n<p>第二处先崩的是块分配器。共享前缀要求 PagedAttention 的块表支持跨请求引用与前段指针拼接，attention 读取时按块表把共享前缀块与私有后缀块拼成逻辑序列。这带来三类可测代价：其一，块表本身从每请求一张扁平表变成“前缀段指针 + 私有段指针”的两级结构，每次 decode step 的逻辑块遍历多一次间接寻址，在 G 条采样 continuous batching 同步推进时，块表解析落在每步的关键路径上，step 延迟随组内私有块数线性抬升；其二，引用计数是全局状态，跨组、跨调度轮次存在，泄漏一次就意味着前缀块永不回收，KV 池单调耗尽——这类故障不报错，只表现为可用块缓慢下降、组排队变长；其三，碎片从“尾部浪费”变成“前缀段与私有段交错”，分配器需要在 LRU 热点保留与当前组引用之间做区分，若淘汰策略不识别“引用中”状态而误回收仍在读的前缀块，attention 会读到被覆写的 KV，数值错误直接污染 logprob 并回流到训练侧。</p>\n<p>带宽与通信侧的代价容易被低估。共享前缀把 G 条采样的 prefill 从 G 次压到 1 次，省下的是算力与 HBM 写带宽；但 decode 阶段每条采样仍要独立读整段前缀 KV 做 attention，读带宽并未减少，反而因为 G 条采样在同一 step 内并发读同一批前缀块，形成对同一 HBM 区域的集中访问。若前缀块恰好落在同一 HBM stack 或同一 L2 分区，会出现热点争抢；跨 NUMA/HBM 分区放置前缀块、把组内采样分散到不同 SM 簇，是缓解手段，但会牺牲块表的局部性。功耗维度上，prefill 的算力峰值被削平，rollout 引擎的功率曲线从“G 次尖峰”变成“一次尖峰 + 长平台”，对 NVL72 机柜的功率封顶更友好，但平台期更长意味着平均功率上升，容量规划要按平台功率而非峰值来配。尾延迟则直接由 $\\rho$ 决定：组完成时间等于最长样本完成时间，前缀共享不改变这一点，只是把“每条都慢”变成“一条慢拖住全组”，SLO 上表现为 P99 组完成时间对 $\\rho$ 敏感。</p>\n<p>规模上限因此不是由 G 单独决定，而是由三元组 $(G,\\ \\rho,\\ \\text{引用计数开销})$ 共同约束。一个可操作的判断：当前缀块占 KV 池比例超过约一半、且组内长度分布的 P99/中位数比超过数倍时，共享带来的显存收益会被驻留放大与块表开销抵消，此时应转向按长度分桶调度——把长尾样本单独成组、短样本组用更小的 G 快速周转，或对超长样本退化为独立 prefill 以尽快释放共享块。这与“分块预填搭载解码”在时间维度混合 prefill/decode 的思路正交：后者优化的是流水线占空，前者优化的是空间复用，两者叠加时要注意块表解析已占用 step 关键路径，不宜再在同步点插入额外拼接。</p>\n<table class=\"mini\"><thead><tr><th>规模变量</th><th>先崩的位置</th><th>可观测信号</th></tr></thead><tbody><tr><td>G 增大</td><td>前缀块驻留被最长样本拉长</td><td>可用块数下降、组排队变长</td></tr><tr><td>$\\rho$ 增大</td><td>组完成时间尾延迟</td><td>P99 组时延、池有效容量折算</td></tr><tr><td>引用计数复杂度</td><td>块分配器与碎片管理</td><td>块表解析耗时、泄漏导致的单调耗尽</td></tr><tr><td>前缀块集中放置</td><td>HBM 读带宽热点</td><td>decode step 时延抖动</td></tr></tbody></table>\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-39\">三十九 · 精度漂移：共享块的低精度一致性约束</h3>\n<p>前缀KV共享把同一份prompt KV交给G条采样共同读取，这带来一个在其他Rollout形态里不突出的失败模式：数值一致性。私有后缀的KV由各条采样独立写入，其数值路径与共享前缀不同——前缀块只经过一次chunked prefill，后缀块则经过逐token decode。若前缀块被量化到NVFP4或FP8而私有块保持更高精度，attention在按块表拼接时会把两种数值域的张量放进同一次softmax归约，logprob分布随之偏移。这种偏移不会在单条采样上表现为崩溃，而是表现为组内G条轨迹的logprob系统性偏低或偏高，训练侧拿到的优势估计被污染。</p>\n<p>诊断的抓手是组内一致性而非绝对误差。对同一prompt的G条采样，在相同前缀、相同已生成后缀的条件下，下一个token的logprob应当只取决于采样随机性。工程上可以在rollout引擎里挂一个旁路校验：每隔若干步，对组内某条采样重算一次attention，强制从高精度前缀副本读取，比较两次logprob的差值。差值超过阈值即判定共享块精度档位与私有块不匹配。代价是这次重算要走一遍完整的前缀读取，带宽开销相当于一次额外的decode步，因此校验频率必须稀疏。</p>\n<div class=\"formula\">$$\\Delta_{\\text{logp}}=\\left|\\log p_{\\text{shared}}(x_t)-\\log p_{\\text{fp16}}(x_t)\\right|,\\quad \\text{alarm if }\\Delta_{\\text{logp}}&gt;\\epsilon$$</div>\n<p>具体例子：8K prompt、G=8的组，前缀块若以FP8存储，其KV字节数为fp16的一半，显存节省显著，但组内若混用不同量化档位的私有块，拼接读取时attention的归约顺序会随块表布局变化，导致同一前缀在不同采样上得到不同结果。判断是：共享块与私有块必须锁定同一精度档位，或在前缀池登记时记录精度标签，块表拼接时拒绝跨档位引用。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-40\">四十 · OOM与引用计数泄漏：池容量被静默吃掉</h3>\n<p>前缀池的显存账本比普通分页KV多一层引用计数。每条采样结束时释放私有块并递减前缀块计数，计数归零才回收。这条路径上任何一次异常退出——采样被调度器抢占、请求被客户端取消、EOS判定与max_len截断竞争——都可能跳过递减操作，使前缀块永远停留在计数大于零的状态。泄漏不报错，KV池只是逐步变小，直到某次新组预填找不到连续块而OOM。此时日志里看不到任何异常请求，只有分配失败。</p>\n<p>监控手段是把引用计数当作一等指标导出：前缀池中计数为1、2…G的块数分布，以及计数大于零但对应rollout group已不在活跃表中的“孤儿块”数量。孤儿块计数单调上升就是泄漏的确诊信号。回收策略上，前缀池需要一条兜底扫描：以rollout group的生命周期为锚，组结束后强制将该组登记过的所有前缀块计数清零并回收，不依赖逐条采样的递减路径。</p>\n<ul>\n<li>显存代价：孤儿块按Lp计，8K prompt在长prompt场景下单块占用可观，几十个孤儿块即可吃掉池内可分配给新组的容量。</li>\n<li>吞吐代价：OOM触发后调度器被迫降低并发组数，continuous batching的批内组数下降，decode步的有效token数减少，单步吞吐塌陷。</li>\n<li>延迟代价：分配失败后的重试与块整理会插入同步点，尾延迟出现尖刺。</li>\n</ul>\n<p>具体例子：一个rollout group的G条采样中，若第3条因客户端断开被异步取消，而取消路径只释放了私有块、未触碰前缀块计数，则该前缀块在组结束后仍被引用。下一轮LRU复用同一prompt时，池内已有该前缀块但计数非零，新组要么重复预填一份，要么等待——两种路径都浪费。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-41\">四十一 · 批抖动与路由不均：组绑定打乱批组成</h3>\n<p>调度器按prompt分组、把G条请求绑定为一个rollout group，这个绑定动作与continuous batching的批组成之间存在张力。正常decode步的批由若干活跃采样拼成，长度相近、推进节奏一致。但rollout group的G条采样共享前缀、后缀长度各异，短样本先EOS退出，批内剩余采样的构成随之变化。若调度器同时维护多个组，某一步的批可能由A组的2条长尾、B组的5条新采样、C组的1条收尾样本拼成，批内token分布极度不均，GPU的SM利用率随步波动。</p>\n<p>更隐蔽的是路由不均。前缀池按prompt为单位登记，热点prompt的前缀块被LRU保留供下一轮复用。若多副本rollout引擎之间没有前缀亲和路由，同一prompt的下一轮采样可能落到没有该前缀副本的实例上，被迫重新预填，共享收益归零。表现为整体预填FLOPs没有降到预期的1/G，而是停在某个中间值。</p>\n<div class=\"formula\">$$\\text{hit}_{\\text{prefix}}=\\frac{\\text{复用前缀块的组数}}{\\text{总组数}},\\quad \\text{预填节省}\\propto \\text{hit}_{\\text{prefix}}\\cdot\\frac{G-1}{G}$$</div>\n<p>诊断抓手是每实例的前缀命中率与批内组构成熵。命中率低于预期说明路由或LRU容量有问题；批内组构成熵过高说明组绑定与批调度没有对齐。工程判断：组绑定应在调度器内做成软约束——同组采样优先同批推进，但允许跨组拼批以填满SM，代价是批内长度方差上升，需要靠chunked prefill的粒度调节来吸收。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-42\">四十二 · 尾延迟尖刺：长尾驻留与块表拼接</h3>\n<p>前缀块被G条采样共享读，只要组内还有一条采样未结束，前缀块就不能释放。组内采样长度差异大时，短样本早已EOS，其私有块已回收，但前缀块仍被最长样本引用，显存驻留时间被长尾拉长。这直接压缩了池内可分配给新组的容量，新组预填被迫排队，尾延迟出现尖刺。尖刺的形态不是单次请求变慢，而是P99随组内长度方差的增大而抬升。</p>\n<p>另一条尖刺来源是块表拼接的读取放大。attention读取时按块表把共享前缀块与私有后缀块拼成逻辑序列，前缀部分被G条采样重复读取。若块表布局使前缀块在物理上分散，每次拼接都要跨多个块描述符，L2命中率下降，单步decode的带宽开销上升。G越大，前缀读取的重复次数越多，这部分带宽不随共享而减少——共享省的是预填算力和显存，不是前缀读取带宽。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>观测信号</th><th>代价落点</th><th>处置</th></tr></thead><tbody><tr><td>长尾驻留</td><td>组内最长样本与最短样本长度差、池可用块数下降</td><td>显存驻留、新组预填排队</td><td>按组设max_len上限，超限样本强制截断并单独记账</td></tr><tr><td>块表拼接放大</td><td>decode步带宽利用率、L2命中率</td><td>单步延迟</td><td>前缀块物理连续化，块表前缀段用单描述符</td></tr><tr><td>批抖动</td><td>批内组构成熵、SM利用率方差</td><td>吞吐波动</td><td>组绑定软约束，允许跨组拼批</td></tr></tbody></table>\n<p>具体例子：G=8的组，7条采样在数百token内EOS，第8条跑到max_len。前缀块在整个长尾期间被占用，池内相当于少了一份Lp的可用容量；若同时有多个这样的组，池的有效容量按组长尾比例缩水，调度器看到的空闲块数远高于实际可分配数。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-43\">四十三 · 监控面与回滚路径</h3>\n<p>监控面要覆盖三层：块层、组层、请求层。块层导出前缀池的引用计数分布、孤儿块数、LRU命中率、按精度标签的块占比；组层导出组内长度方差、组长尾驻留时长、组结束时前缀块回收延迟；请求层导出每请求的预填时间、decode步延迟分位、logprob校验差值。三层指标对齐到同一rollout group id，才能在尖刺出现时定位是精度、泄漏还是长尾。</p>\n<p>回滚不是单一开关，而是分级降级。第一级：关闭跨组前缀复用，只保留组内共享，消除路由不均与LRU争抢；第二级：关闭前缀池的LRU保留，组结束即回收，消除孤儿块累积与热点争抢；第三级：整体退回每条采样独立预填，即放弃共享，回到G倍预填与G倍KV的基线。每一级都对应明确的触发条件：孤儿块计数持续上升触发第一级，前缀命中率跌破阈值触发第二级，logprob校验差值超阈值且锁定精度档位后仍不收敛触发第三级。</p>\n<ul>\n<li>回滚代价：退回独立预填意味着预填FLOPs回到G倍，长prompt下预填时间从1/G回到1，rollout总时长显著抬升；KV显存回到G·(Lp+Lo)，池容量需求按G倍放大。</li>\n<li>回滚粒度：应按prompt或按组回滚，而非全局，避免一个热点prompt的精度问题拖垮整个rollout引擎。</li>\n<li>可观测前提：回滚决策依赖块层与组层指标的低延迟导出，指标采集本身不能引入同步点，否则诊断动作变成新的尾延迟来源。</li>\n</ul>\n<p>工程判断落在引用计数的兜底扫描上：以rollout group生命周期为锚的强制回收，比逐条采样递减更可靠，因为它把泄漏的检测从“计数是否归零”变成“组是否还活着”，后者是调度器本来就维护的状态。前缀池的容量规划应把孤儿块与长尾驻留作为两个独立的预留项计入，而不是假设共享收益全额兑现。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-44\">四十四 · 长尾驻留、引用泄漏与误淘汰：共享前缀池的三类失效面</h3>\n<p>前缀KV共享把显存账从$G\\cdot(L_p+L_o)$压到$L_p+G\\cdot L_o$，但节省量$(G-1)L_p$并非即时兑现——它被组内最长样本的驻留时间锁定。设组内采样长度服从重尾分布，第$i$条采样在$t_i$时刻结束，前缀块的释放时刻为$\\max_i t_i$而非均值，于是池内被占用的有效容量在整组生命周期内恒等于$L_p$加上仍在推进的私有块之和。短样本先EOS只释放$L_o$，前缀块引用计数从$G$递减到$G-k$却始终大于零。工程后果是调度器看到的空闲块数低于按平均长度估算的预期值，continuous batching的批扩张在组尾阶段被显存而非算力卡住，吞吐出现可观测的塌陷。诊断上应把“前缀块引用计数分布”与“组内已完成采样比例”作为一对联合指标上报：当完成比例超过某阈值而引用计数仍为1的块数居高不下，即判定长尾驻留已经发生，此时应缩短该组的max_len或对超长样本单独降级为不共享路径。</p>\n<p>第二类失效是引用计数泄漏。块表跨请求共享要求分配器在fork时+1、在采样结束释放私有块时−1，任何一条异常路径——采样被抢占后重调度、EOS与max_len同时触发、组被取消——漏掉一次递减，前缀块就永不归零。泄漏不报错，只表现为池容量单调下降，直到新组无法分配前缀块而退化为逐条预填，rollout预填时间悄悄回到$G$倍。监控口径应是“登记块数−回收块数−在引用块数”的恒等残差，残差持续为正即泄漏；配合周期性强制对账（遍历块表重建引用计数）作为兜底，代价是一次全池扫描的显存带宽开销，只能在低峰执行。</p>\n<p>第三类来自LRU与在用块的冲突。热点前缀保留策略按最近使用淘汰，但“最近使用”与“仍被引用”是两个维度：一个块可能刚被新组登记、引用计数为正，却在LRU序上因旧时间戳排在末尾而被选中淘汰，attention按块表读到已回收的物理块，输出数值错乱而非崩溃，这类精度问题最难定位。判据必须把引用计数作为淘汰的硬门禁，LRU只在计数为零的候选集内排序。下表给出三类失效的对照。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>可观测信号</th><th>系统代价</th><th>处置</th></tr></thead><tbody><tr><td>长尾驻留</td><td>完成比例高但计数为1的块多</td><td>批扩张受阻，吞吐塌陷</td><td>限max_len或超长样本走非共享路径</td></tr><tr><td>引用泄漏</td><td>登记−回收−在用残差为正</td><td>池容量单调下降，退化到G倍预填</td><td>周期对账重建计数</td></tr><tr><td>误淘汰在用块</td><td>共享前缀段logprob偏移</td><td>数值错误，非崩溃</td><td>计数为零才进LRU候选</td></tr></tbody></table>\n<p>回滚路径要按粒度设计：单组级回滚是把该组从共享模式切回逐条预填，代价是这一组的预填FLOPs回到$G$倍但不动全局池；引擎级回滚是关闭前缀池、清空块表并重建分配器，代价是丢失全部热点前缀、下一轮rollout预填时间整体回升。精度类失效（误淘汰）必须走引擎级并保留出错块的块表快照用于复现，因为单组回滚无法证明其他组未读到同一物理块。</p>\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-45\">四十五 · 对照轴：空间共享、时间混合、价值筛选</h3>\n<p>把同族算法放在同一张坐标上，判据不是“谁更先进”，而是“它把冗余消在哪一维”。Rollout前缀KV共享消的是空间维冗余：同一prompt的G条采样本应各自持有一份完全相同的prompt KV，算法让这份KV在物理上只存在一份，G条采样通过块表引用同一组前缀块。分块预填搭载解码消的是时间维冗余：它把prefill的chunk与decode的step在同一引擎的同一时间片上交错填充，让prefill的长尾不空转、decode的短步不浪费SM。在线Rollout剪枝消的是样本维冗余：它承认G条轨迹中有一部分价值低，直接在生成过程中放弃，用减少G换取单条轨迹更长的预算。三者并不互斥，但优先级不同——空间共享不改变采样条数，时间混合不改变KV归属，价值筛选改变的是“算多少条”。</p>\n<p>由此得到第一个选择判据：若瓶颈是预填算力与KV显存随G线性膨胀，且G条轨迹都必须保留（RL目标需要组内相对优势估计，丢弃样本会破坏baseline），则前缀KV共享是唯一不损失样本分布的选项。若瓶颈是引擎在长prompt下prefill与decode互相阻塞、SM利用率出现周期性凹陷，则时间混合优先。若瓶颈是显存被大量低价值轨迹占满、且训练侧能接受变长组，则剪枝优先。三者的代价结构也不同：前缀共享把代价推给块分配器的引用计数与长尾驻留；时间混合把代价推给调度器的chunk切分与优先级反转；剪枝把代价推给组内样本数不一致带来的梯度方差。</p>\n<p>一个具体例子：8K prompt、G=8的rollout组，朴素实现下prompt KV被算8次、存8份，预填算力占rollout总FLOPs的30%以上。前缀共享把预填FLOPs压到1/8，KV显存从G·(Lp+Lo)降到Lp+G·Lo，节省(G−1)Lp。此时若组内最长样本比最短样本长出一大截，前缀块的驻留时间被长尾拉长，显存池的实际可用容量低于账面——这正是空间共享把时间维的问题继承了下来，也是它与时间混合算法需要联合部署的原因。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-46\">四十六 · 决策表：按负载形态与瓶颈定位选型</h3>\n<p>下表把四个同族算法按“冗余维度、触发条件、主要代价、不适用情形”四列对齐。读法是从左到右逐列排除：先看冗余维度是否匹配当前瓶颈，再看触发条件是否成立，最后确认代价是否在SLO预算内。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>算法</th><th>消除的冗余</th><th>触发条件</th><th>主要代价</th><th>不适用</th></tr>\n</thead>\n<tbody>\n<tr><td>Rollout前缀KV共享</td><td>空间：G份prompt KV合一</td><td>同一prompt多采样、Lp占比高、G条全保留</td><td>引用计数与碎片管理；长尾驻留</td><td>G=1或prompt极短；组内长度方差极大</td></tr>\n<tr><td>分块预填搭载解码</td><td>时间：prefill与decode交错填隙</td><td>长短请求混批、SM出现周期性空闲</td><td>chunk切分与调度复杂度；decode延迟抖动</td><td>请求同质、prefill占比低</td></tr>\n<tr><td>在线Rollout剪枝</td><td>样本：放弃低价值轨迹</td><td>显存被低价值轨迹占满、训练可接受变长组</td><td>组内样本数不一致，梯度方差上升</td><td>需要完整组做相对优势估计</td></tr>\n<tr><td>分离式预填解码Rollout</td><td>资源：prefill与decode分池</td><td>两阶段资源配比差异大、需独立扩缩容</td><td>KV跨池传输带宽；池间背压</td><td>集群规模小、传输成本高于收益</td></tr>\n</tbody>\n</table>\n<p>决策顺序建议为：先判断G条轨迹是否必须全保留。若必须，排除剪枝；若可弃，剪枝的显存收益最直接。再判断Lp在总KV中的占比：Lp远大于Lo时前缀共享的节省量(G−1)Lp接近上限，收益随Lp占比单调上升；Lp与Lo同量级时节省有限，不值得引入引用计数。最后判断prefill与decode是否在同一引擎内互相阻塞：若是，叠加时间混合或分离式部署；若否，前缀共享单独部署即可。</p>\n<p>代价量化上，前缀共享的显存收益可直接写成比值：节省占比接近(G−1)Lp / [G·(Lp+Lo)]。G越大、Lp/(Lp+Lo)越接近1，该比值越接近(G−1)/G。而它的延迟收益体现在预填时间近似降为1/G，前提是预填阶段本身不被组内最长样本的decode拖住——这要求调度器把同一组的prefill一次性做完再进入decode循环，否则共享块的登记会被拆散。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-47\">四十七 · 与时间混合算法的组合判据</h3>\n<p>前缀KV共享与分块预填搭载解码的组合不是简单叠加，而是有明确的接口条件。前者要求同一prompt的G条请求在prefill完成后同时进入decode，块表前段指向同一组前缀块；后者要求引擎在每个step内既能推进decode请求、又能插入prefill chunk。组合后的调度伪代码思路是：按rollout group分组，组内先做一次chunked prefill并登记前缀块，随后该组整体作为一个decode批次参与continuous batching；引擎在组间空隙插入其他组的prefill chunk。这样前缀块的引用计数在组进入decode时一次性加G，在组内最后一条样本结束时归零。</p>\n<div class=\"formula\">$$T_{\\text{rollout}} \\approx T_{\\text{prefill}}(L_p) + G\\cdot T_{\\text{decode}}(L_o)$$</div>\n<p>组合的收益边界在于：时间混合填的是组间空隙，若所有组都是长prompt、预填占比高，空隙本身很少，时间混合的边际收益下降；反之若组间长短混杂，空隙多，组合收益显著。代价方面，组合把调度器的状态空间从“请求级”扩到“组级+请求级”，组内某条样本提前EOS时，该样本退出decode批次但前缀块引用不减，调度器必须区分“批次成员退出”与“组引用释放”两件事，否则引用计数泄漏会让前缀块永不回收，KV池逐步耗尽。</p>\n<p>具体例子：一个rollout批次里混有8K prompt的组与短prompt的组。短组先完成prefill进入decode，长组还在chunked prefill中；若引擎支持时间混合，短组的decode step可以填进长组prefill chunk之间的空隙，SM不空转。此时前缀共享让长组的G条采样只付一次8K预填，时间混合让这次预填的chunk不独占时间线。两者叠加的收益是“预填总量降为1/G”乘以“预填时间被填隙摊薄”，但显存侧的长尾驻留问题不变——长组的前缀块仍要等组内最长样本结束才释放。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-48\">四十八 · 与价值筛选算法的取舍：样本分布 vs 显存回收</h3>\n<p>在线Rollout剪枝与前缀共享解决的是同一显存压力下的两种哲学。剪枝的逻辑是“少算几条”，前缀共享的逻辑是“每条都算但不重复算”。前者直接减少G的有效值，后者保持G不变但把每条的边际成本压低。在RL后训练里这个区别很关键：组内相对优势估计需要G条轨迹的回报分布，剪枝造成组内样本数不一致，baseline的估计方差上升，可能抵消显存收益；前缀共享不改变样本数，分布无偏，代价是工程复杂度。</p>\n<p>取舍判据可以写成：若训练侧对组内样本数敏感（例如用组均值作baseline），前缀共享优先；若显存是硬约束且训练侧已实现变长组的归一化，剪枝优先。两者也可分层：先用前缀共享把prompt KV压到1份，再用剪枝在decode中途放弃明显低价值的轨迹，此时被放弃样本的私有块立即释放，但前缀块仍被剩余样本引用——剪枝释放的是Lo侧，前缀共享压缩的是Lp侧，二者释放的显存区域不重叠，可以叠加而不冲突。</p>\n<p>代价上，剪枝的决策点需要读取部分生成结果做价值判断，这要求decode循环中插入判断逻辑，增加了每步的调度开销；前缀共享的开销集中在块分配器的引用计数操作上，是O(1)的元数据更新，但跨请求共享使碎片管理复杂化。一个具体场景：G=8、Lp=8K、Lo较短时，前缀共享省下7份8K前缀KV，剪枝若再弃掉3条样本，省下3份Lo；前者是显存大头，后者是零头。这说明在长prompt场景下，前缀共享的收益量级高于剪枝，剪枝应作为前缀共享之后的二级手段。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-49\">四十九 · 与分离式部署的边界：传输成本决定分层</h3>\n<p>分离式预填解码Rollout把prefill池与decode池分开，KV需要跨池传输。前缀KV共享与它的关系是：共享块在prefill池生成后，要被G条decode请求引用，跨池传输的就不是G份prompt KV，而是一份共享前缀块加G条各自的私有后缀。这直接改变了分离式部署的带宽账：传输量从G·(Lp+Lo)降为Lp+G·Lo，跨池链路的压力随G增大而相对下降。反过来说，若不做前缀共享，分离式部署在长prompt、大G下会被KV传输带宽卡死，池间背压传导到调度器，prefill池被迫降速。</p>\n<p>但共享块跨池引用带来一个额外约束：引用计数必须跨池一致。prefill池不能在前缀块仍被decode池引用时回收它，这要求两池共享同一份块表元数据或至少共享引用计数状态，实现上等价于把块分配器提升为集群级服务。代价是元数据访问的延迟进入关键路径，若块表查询走网络，每个decode step的attention寻址都要付一次远程元数据开销。工程判断是：G较大且Lp较长时，跨池共享的带宽节省足以覆盖元数据开销；G小或Lp短时，不如让decode池本地重建前缀，避免跨池引用计数的一致性维护。</p>\n<p>具体例子：GB200 NVL72机架内，NVLink 5的带宽让跨池KV传输相对廉价，前缀共享的收益更多体现在显存而非带宽；跨机架部署时，KV传输走NIXL与NCCL路径，带宽成为约束，此时前缀共享把传输量压到Lp+G·Lo，是分离式部署能否成立的前提条件之一。这也解释了为什么前缀共享在长prompt、大G的rollout里常与分离式部署同现：前者压显存与传输量，后者解资源配比，二者共同把rollout的预填成本从“每样本一份”降到“每组一份”。</p>\n\n<h3 id=\"alg-rollout-prefix-cache-sharing-sec-50\">五十 · 选型的工程判断线</h3>\n<p>把上述对照收敛成一条可执行的判断线：先测Lp/(Lp+Lo)与G。若该比值高且G≥4，前缀共享是默认选项，因为节省量(G−1)Lp已接近显存账本的主体；若比值低，前缀共享的引用计数复杂度换不来对应收益，应转向时间混合或直接优化decode。再测组内样本长度方差：方差大时前缀块的长尾驻留会吃掉账面节省，需配合LRU淘汰策略区分“引用中块”与“可淘汰块”，否则误回收仍在读的前缀块会引发错误而非性能下降。最后测块分配器的引用计数开销：跨请求共享使每次块表拼接多一次间接寻址，若attention寻址成为decode step的瓶颈，说明共享粒度太细，应把前缀块做大以减少块表项数。</p>\n<p>一个具体的工程判断：在8K prompt、G=8、预填占rollout FLOPs 30%以上的负载里，前缀共享把预填时间近似降为1/G，这个收益的量级足以覆盖引用计数的实现成本；但如果组内最长样本比中位数长出一倍以上，前缀块的驻留时间被长尾拉长，KV池的实际可用容量低于账面，此时应把前缀共享与在线剪枝组合——剪枝缩短长尾，前缀共享压缩前缀，两者分别作用于驻留时间与占用空间。选型不是挑一个算法，而是确认当前瓶颈落在哪一维冗余上，再决定用空间共享、时间混合还是价值筛选去消它；当瓶颈同时落在两维时，组合的接口条件是块表引用计数在组级与请求级之间保持一致，这条一致性线一旦断裂，任何组合收益都会被引用泄漏或误回收抵消。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2026 · 长尾样本与rollout吞吐</td></tr><tr><td>解决什么</td><td>RL后训练的rollout阶段对同一prompt会采样G条轨迹，每条轨迹共享同一段prompt前缀，若每条都从头预填，…</td></tr><tr><td>一句话机制</td><td>在rollout引擎内以prompt为单位建立前缀KV池，同一prompt的G条采样共享一份prompt KV，采样时…</td></tr><tr><td>代价与失效</td><td>前缀块被G条采样共享读，若组内采样长度差异大，短样本先结束也无法释放前缀块，需等最长样本结束，造成显存驻留时间被长尾拉长；块表跨组引用使P…</td></tr><tr><td>后继</td><td>rollout上下文bandit调度</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-rollout-prefix-cache-sharing · 共 8 个片段</p>\n";break;}}})();
